import Foundation

/// 수학 개념 사전 (초등 → 대학교)
extension DoitCurriculum {
    static let math: [CurriculumEntry] = [
        // MARK: - 초등

        ce(.elementary, "자연수의 계산", ["받아올림과 받아내림", "덧셈과 뺄셈", "carrying"], "덧셈에서 같은 자리 수끼리 더한 값이 10 이상이면 바로 윗자리로 1을 올려 주는데, 이것을 받아올림이라고 해요. 뺄셈에서 같은 자리 수끼리 뺄 수 없으면 윗자리에서 10을 빌려 오는데, 이것을 받아내림이라고 해요.\n예: 47 + 38 = 85 (7 + 8 = 15이므로 5를 쓰고 1을 받아올려요), 52 − 27 = 25 (십의 자리에서 10을 받아내려 12 − 7 = 5)"),
        ce(.elementary, "자연수의 계산", ["곱셈", "구구단", "multiplication"], "곱셈은 같은 수를 여러 번 더하는 것을 간단히 나타낸 계산이에요. 두 수의 순서를 바꾸어 곱해도 결과가 같아요(교환법칙). 두 자리 수끼리의 곱셈은 자리를 나누어 곱한 뒤 더하면 돼요.\n예: 3 × 4 = 3 + 3 + 3 + 3 = 12, 24 × 13 = 24 × 10 + 24 × 3 = 240 + 72 = 312"),
        ce(.elementary, "자연수의 계산", ["나눗셈", "몫과 나머지", "division"], "나눗셈은 어떤 수를 똑같이 나누거나 몇 번 덜어 낼 수 있는지 구하는 계산이에요. 나머지는 항상 나누는 수보다 작아야 하고, (나누는 수) × (몫) + (나머지) = (나누어지는 수)로 검산할 수 있어요. 나머지가 0이면 나누어떨어진다고 해요.\n예: 29 ÷ 4 = 7 … 1, 검산: 4 × 7 + 1 = 29"),
        ce(.elementary, "자연수의 계산", ["혼합 계산의 순서", "계산 순서", "order of operations"], "덧셈·뺄셈·곱셈·나눗셈이 섞인 식은 ① 괄호 안 ② 곱셈과 나눗셈(앞에서부터) ③ 덧셈과 뺄셈(앞에서부터) 순서로 계산해요. 괄호가 있으면 괄호 안을 가장 먼저 계산해요.\n예: 12 + 18 ÷ 3 × 2 = 12 + 6 × 2 = 12 + 12 = 24, (12 + 18) ÷ 3 × 2 = 30 ÷ 3 × 2 = 20"),

        ce(.elementary, "수의 범위와 어림하기", ["이상과 이하", "초과와 미만", "수의 범위"], "이상은 기준이 되는 수와 같거나 큰 수, 이하는 기준이 되는 수와 같거나 작은 수예요. 초과는 기준이 되는 수보다 큰 수, 미만은 기준이 되는 수보다 작은 수로, 기준이 되는 수는 포함하지 않아요.\n예: 10 이상 15 미만인 자연수는 10, 11, 12, 13, 14예요."),
        ce(.elementary, "수의 범위와 어림하기", ["어림하기", "올림, 버림, 반올림", "rounding"], "올림은 구하려는 자리 아래 수를 올려서, 버림은 구하려는 자리 아래 수를 버려서 나타내는 방법이에요. 반올림은 구하려는 자리 바로 아래 숫자가 0, 1, 2, 3, 4이면 버리고, 5, 6, 7, 8, 9이면 올려요.\n예: 3478을 백의 자리까지 나타내면 올림 3500, 버림 3400, 반올림 3500(십의 자리 숫자가 7이므로 올려요)"),

        ce(.elementary, "분수와 소수", ["분수", "분자와 분모", "진분수, 가분수, 대분수", "fraction"], "분수는 전체를 똑같이 나눈 것 중의 몇 부분인지를 나타내는 수예요. 가로선 아래의 수를 분모, 위의 수를 분자라고 해요. 분자가 분모보다 작으면 진분수, 분자가 분모와 같거나 크면 가분수, 자연수와 진분수로 이루어진 수를 대분수라고 해요.\n예: 피자 8조각 중 3조각은 3/8, 가분수 7/4 = 대분수 1과 3/4"),
        ce(.elementary, "분수와 소수", ["약분과 통분", "약분", "통분", "기약분수"], "약분은 분모와 분자를 그 공약수로 나누어 간단한 분수로 만드는 거예요. 더 이상 약분할 수 없는 분수를 기약분수라고 해요. 통분은 분수의 크기는 그대로 두고 분모를 같게 만드는 것으로, 보통 두 분모의 최소공배수를 공통분모로 써요.\n예: 12/18 = 2/3 (최대공약수 6으로 나눔), 1/4과 1/6을 통분하면 3/12와 2/12"),
        ce(.elementary, "분수와 소수", ["분수의 덧셈과 뺄셈", "분모가 다른 분수의 덧셈"], "분모가 같으면 분모는 그대로 두고 분자끼리 더하거나 빼요. 분모가 다르면 먼저 통분한 뒤 분자끼리 계산하고, 결과는 기약분수로 나타내요. 대분수는 가분수로 바꾸거나 자연수 부분과 분수 부분을 따로 계산해요.\n예: 1/4 + 1/6 = 3/12 + 2/12 = 5/12, 2와 1/3 − 1과 1/2 = 7/3 − 3/2 = 14/6 − 9/6 = 5/6"),
        ce(.elementary, "분수와 소수", ["분수의 곱셈", "분수 × 분수"], "분수끼리 곱할 때는 분자는 분자끼리, 분모는 분모끼리 곱해요. 계산 도중에 약분하면 더 간단해요. 대분수는 가분수로 바꾼 뒤 곱해요.\n예: 2/3 × 3/4 = 6/12 = 1/2, 1과 1/2 × 4 = 3/2 × 4 = 6"),
        ce(.elementary, "분수와 소수", ["분수의 나눗셈", "역수", "분수 ÷ 분수"], "분수로 나눌 때는 나누는 분수의 분모와 분자를 바꾼 수(역수)를 곱해요. 분모가 같은 분수끼리의 나눗셈은 분자끼리 나누어도 돼요.\n예: 3/4 ÷ 2/5 = 3/4 × 5/2 = 15/8 = 1과 7/8, 6/7 ÷ 2/7 = 6 ÷ 2 = 3"),
        ce(.elementary, "분수와 소수", ["소수", "소수점", "decimal"], "소수는 0.1, 0.25처럼 소수점을 사용해 1보다 작은 부분을 나타낸 수예요. 0.1은 1/10, 0.01은 1/100, 0.001은 1/1000과 같아요. 약수가 1과 자기 자신뿐인 수를 뜻하는 소수(素數)와는 다른 개념이에요.\n예: 3.47은 3과 0.4와 0.07을 합한 수이고, '삼 점 사칠'이라고 읽어요. 3/4 = 3 ÷ 4 = 0.75"),
        ce(.elementary, "분수와 소수", ["소수의 곱셈", "소수 × 소수", "decimal multiplication"], "소수의 곱셈은 소수점을 무시하고 자연수처럼 곱한 다음, 곱하는 두 수의 소수점 아래 자릿수를 더한 만큼 소수점을 찍어요.\n예: 1.2 × 0.35 → 12 × 35 = 420이고, 소수점 아래 자릿수가 1 + 2 = 3이므로 0.420 = 0.42"),
        ce(.elementary, "분수와 소수", ["소수의 나눗셈", "소수 ÷ 소수", "decimal division"], "나누는 수가 소수이면 나누는 수와 나누어지는 수의 소수점을 똑같이 오른쪽으로 옮겨 나누는 수를 자연수로 만든 뒤 계산해요. 몫의 소수점은 옮긴 나누어지는 수의 소수점 위치에 맞춰 찍어요.\n예: 7.2 ÷ 0.3 = 72 ÷ 3 = 24, 4.5 ÷ 6 = 0.75"),

        ce(.elementary, "약수와 배수", ["약수", "divisor"], "어떤 수를 나누어떨어지게 하는 수를 그 수의 약수라고 해요. 1은 모든 자연수의 약수이고, 자기 자신도 항상 약수예요.\n예: 12를 1, 2, 3, 4, 6, 12로 나누면 모두 나누어떨어지므로 12의 약수는 1, 2, 3, 4, 6, 12예요."),
        ce(.elementary, "약수와 배수", ["배수", "multiple"], "어떤 수를 1배, 2배, 3배, … 한 수를 그 수의 배수라고 해요. 배수는 끝없이 많아요. 가가 나의 배수이면 나는 가의 약수예요.\n예: 4의 배수는 4, 8, 12, 16, …이고, 12는 4의 배수이므로 4는 12의 약수예요."),
        ce(.elementary, "약수와 배수", ["최대공약수", "공약수", "GCD"], "두 수의 공통인 약수를 공약수, 그중 가장 큰 수를 최대공약수라고 해요. 공약수는 모두 최대공약수의 약수예요. 두 수를 공통으로 나누는 수로 계속 나누어 그 수들을 곱하면 최대공약수가 나와요.\n예: 18과 24의 공약수는 1, 2, 3, 6이고 최대공약수는 6이에요."),
        ce(.elementary, "약수와 배수", ["최소공배수", "공배수", "LCM"], "두 수의 공통인 배수를 공배수, 그중 가장 작은 수를 최소공배수라고 해요. 공배수는 모두 최소공배수의 배수예요. 두 자연수의 곱은 (최대공약수) × (최소공배수)와 같아요.\n예: 6과 8의 공배수는 24, 48, 72, …이고 최소공배수는 24예요. 6 × 8 = 48 = 2 × 24"),

        ce(.elementary, "비와 비율", ["비", "ratio", "기준량과 비교하는 양"], "두 수를 나눗셈으로 비교하기 위해 기호 : 를 사용해 나타낸 것을 비라고 해요. 3 : 5는 '3 대 5'라고 읽고, 기호 : 의 오른쪽에 있는 5가 기준량, 왼쪽에 있는 3이 비교하는 양이에요.\n예: 남학생 12명, 여학생 15명이면 남학생 수와 여학생 수의 비는 12 : 15 = 4 : 5예요."),
        ce(.elementary, "비와 비율", ["비율", "비의 값"], "비율은 기준량에 대한 비교하는 양의 크기로, (비율) = (비교하는 양) ÷ (기준량)이에요. 분수나 소수로 나타내요.\n예: 3 : 5의 비율은 3/5 = 0.6, 400 m를 50초에 달리면 걸린 시간에 대한 거리의 비율(속력)은 400 ÷ 50 = 8로 초속 8 m예요."),
        ce(.elementary, "비와 비율", ["백분율", "퍼센트", "%"], "백분율은 기준량을 100으로 할 때의 비율로, 기호 %(퍼센트)를 써요. (백분율) = (비율) × 100이에요.\n예: 반 20명 중 7명이 안경을 쓰면 7/20 × 100 = 35%, 30000원짜리 옷을 20% 할인하면 30000 × 0.2 = 6000원을 깎아 24000원이에요."),
        ce(.elementary, "비와 비율", ["비례식", "외항과 내항", "비의 성질"], "비율이 같은 두 비를 등호로 나타낸 식을 비례식이라고 해요. 가 : 나 = 다 : 라에서 바깥쪽 가, 라를 외항, 안쪽 나, 다를 내항이라고 하며, 외항의 곱과 내항의 곱은 같아요. 비의 전항과 후항에 0이 아닌 같은 수를 곱하거나 나누어도 비율은 같아요.\n예: 3 : 4 = □ : 20이면 4 × □ = 3 × 20 = 60이므로 □ = 15"),

        ce(.elementary, "평면도형", ["각", "직각, 예각, 둔각", "angle"], "한 점에서 그은 두 반직선으로 이루어진 도형을 각이라고 하고, 각의 크기는 도(°)로 나타내요. 직각은 90°, 예각은 0°보다 크고 90°보다 작은 각, 둔각은 90°보다 크고 180°보다 작은 각이에요.\n예: 시계가 3시를 가리킬 때 두 바늘이 이루는 작은 쪽 각은 90°로 직각, 2시일 때는 60°로 예각이에요."),
        ce(.elementary, "평면도형", ["삼각형의 세 각의 합", "사각형의 네 각의 합", "내각의 합"], "삼각형의 세 각의 크기의 합은 항상 180°, 사각형의 네 각의 크기의 합은 항상 360°예요. 사각형은 대각선으로 삼각형 2개로 나눌 수 있기 때문이에요.\n예: 두 각이 50°, 70°인 삼각형의 나머지 한 각은 180° − 50° − 70° = 60°"),
        ce(.elementary, "평면도형", ["삼각형의 분류", "이등변삼각형", "정삼각형", "직각삼각형"], "변의 길이에 따라 두 변의 길이가 같은 이등변삼각형, 세 변의 길이가 같은 정삼각형으로 나눠요. 각에 따라 세 각이 모두 예각인 예각삼각형, 한 각이 직각인 직각삼각형, 한 각이 둔각인 둔각삼각형으로 나눠요. 이등변삼각형은 두 밑각의 크기가 같고, 정삼각형은 세 각이 모두 60°예요.\n예: 꼭지각이 40°인 이등변삼각형의 밑각은 (180° − 40°) ÷ 2 = 70°"),
        ce(.elementary, "평면도형", ["사각형의 분류", "평행사변형", "마름모", "사다리꼴"], "평행한 변이 한 쌍이라도 있으면 사다리꼴, 마주 보는 두 쌍의 변이 서로 평행하면 평행사변형이에요. 네 변의 길이가 모두 같으면 마름모, 네 각이 모두 직각이면 직사각형, 네 변의 길이가 같고 네 각이 직각이면 정사각형이에요.\n예: 정사각형은 직사각형이면서 마름모이고, 평행사변형은 마주 보는 변의 길이와 마주 보는 각의 크기가 각각 같아요."),
        ce(.elementary, "평면도형", ["원의 구성 요소", "반지름과 지름", "원의 중심"], "원의 한가운데 점을 원의 중심, 중심과 원 위의 한 점을 이은 선분을 반지름, 중심을 지나며 원 위의 두 점을 이은 선분을 지름이라고 해요. 한 원에서 반지름은 모두 같고, 지름은 반지름의 2배예요. 지름은 원 안에 그을 수 있는 가장 긴 선분이에요.\n예: 반지름이 4 cm인 원의 지름은 8 cm예요."),
        ce(.elementary, "평면도형", ["선대칭도형과 점대칭도형", "선대칭도형", "점대칭도형", "대칭"], "한 직선을 따라 접었을 때 완전히 겹치는 도형을 선대칭도형, 그 직선을 대칭축이라고 해요. 한 점을 중심으로 180° 돌렸을 때 처음 도형과 완전히 겹치는 도형을 점대칭도형, 그 점을 대칭의 중심이라고 해요.\n예: 정사각형은 대칭축이 4개인 선대칭도형이면서 점대칭도형이에요. 평행사변형은 점대칭도형이지만 보통 선대칭도형은 아니에요."),

        ce(.elementary, "다각형의 둘레와 넓이", ["다각형의 둘레", "둘레", "perimeter"], "둘레는 도형의 테두리 길이예요. 직사각형의 둘레는 (가로 + 세로) × 2, 정다각형의 둘레는 (한 변의 길이) × (변의 수)예요.\n예: 가로 7 cm, 세로 4 cm인 직사각형의 둘레는 (7 + 4) × 2 = 22 cm, 한 변이 5 cm인 정육각형의 둘레는 5 × 6 = 30 cm"),
        ce(.elementary, "다각형의 둘레와 넓이", ["직사각형의 넓이", "정사각형의 넓이", "넓이의 단위"], "넓이는 평면도형이 차지하는 크기로, 한 변이 1 cm인 정사각형의 넓이 1 cm²를 단위로 써요. 직사각형의 넓이는 가로 × 세로, 정사각형의 넓이는 한 변 × 한 변이에요. 1 m² = 10000 cm², 1 km² = 1000000 m²예요.\n예: 가로 7 cm, 세로 4 cm인 직사각형의 넓이는 7 × 4 = 28 cm²"),
        ce(.elementary, "다각형의 둘레와 넓이", ["평행사변형의 넓이", "area of a parallelogram"], "평행사변형의 넓이는 (밑변) × (높이)예요. 한쪽 삼각형을 잘라 반대쪽으로 옮기면 직사각형이 되기 때문이에요. 높이는 밑변과 마주 보는 변 사이의 수직 거리예요.\n예: 밑변 8 cm, 높이 5 cm인 평행사변형의 넓이는 8 × 5 = 40 cm²"),
        ce(.elementary, "다각형의 둘레와 넓이", ["삼각형의 넓이", "삼각형 넓이 공식", "area of a triangle"], "삼각형의 넓이는 (밑변) × (높이) ÷ 2예요. 똑같은 삼각형 2개를 붙이면 평행사변형이 되기 때문이에요. 밑변과 높이가 같으면 모양이 달라도 넓이가 같아요.\n예: 밑변 10 cm, 높이 6 cm인 삼각형의 넓이는 10 × 6 ÷ 2 = 30 cm²"),
        ce(.elementary, "다각형의 둘레와 넓이", ["사다리꼴의 넓이", "area of a trapezoid"], "사다리꼴의 넓이는 (윗변 + 아랫변) × (높이) ÷ 2예요. 똑같은 사다리꼴 2개를 거꾸로 붙이면 밑변이 (윗변 + 아랫변)인 평행사변형이 되기 때문이에요.\n예: 윗변 4 cm, 아랫변 8 cm, 높이 5 cm인 사다리꼴의 넓이는 (4 + 8) × 5 ÷ 2 = 30 cm²"),
        ce(.elementary, "다각형의 둘레와 넓이", ["마름모의 넓이", "area of a rhombus"], "마름모의 넓이는 (한 대각선의 길이) × (다른 대각선의 길이) ÷ 2예요. 마름모를 둘러싼 직사각형 넓이의 절반이기 때문이에요.\n예: 두 대각선이 6 cm, 10 cm인 마름모의 넓이는 6 × 10 ÷ 2 = 30 cm²"),

        ce(.elementary, "원의 넓이", ["원주율", "원주", "π"], "원의 둘레를 원주라고 하고, 지름에 대한 원주의 비율을 원주율이라고 해요. 원주율은 원의 크기와 상관없이 일정하며 3.14159…로 끝없이 이어지므로 보통 3.14로 어림해서 써요. 원주 = 지름 × 원주율이에요.\n예: 지름이 10 cm인 원의 원주는 10 × 3.14 = 31.4 cm"),
        ce(.elementary, "원의 넓이", ["원의 넓이", "area of a circle"], "원을 잘게 잘라 엇갈려 붙이면 가로가 원주의 절반, 세로가 반지름인 직사각형에 가까워져요. 그래서 원의 넓이 = 반지름 × 반지름 × 원주율이에요.\n예: 반지름이 5 cm인 원의 넓이는 5 × 5 × 3.14 = 78.5 cm²"),

        ce(.elementary, "입체도형", ["직육면체와 정육면체", "직육면체", "정육면체"], "직사각형 6개로 둘러싸인 도형을 직육면체, 정사각형 6개로 둘러싸인 도형을 정육면체라고 해요. 둘 다 면 6개, 모서리 12개, 꼭짓점 8개가 있고, 마주 보는 면끼리 평행해요. 정육면체도 직육면체의 한 종류예요.\n예: 주사위는 정육면체, 과자 상자는 직육면체 모양이에요."),
        ce(.elementary, "입체도형", ["각기둥과 각뿔", "각기둥", "각뿔"], "두 밑면이 평행하고 합동인 다각형이며 옆면이 직사각형인 입체도형을 각기둥, 밑면이 다각형이고 옆면이 삼각형인 뿔 모양 입체도형을 각뿔이라고 해요. n각기둥은 꼭짓점 2n개, 면 (n + 2)개, 모서리 3n개이고, n각뿔은 꼭짓점 (n + 1)개, 면 (n + 1)개, 모서리 2n개예요.\n예: 삼각기둥은 꼭짓점 6, 면 5, 모서리 9개, 사각뿔은 꼭짓점 5, 면 5, 모서리 8개"),
        ce(.elementary, "입체도형", ["원기둥, 원뿔, 구", "원기둥", "원뿔", "구"], "원기둥은 평행하고 합동인 두 원을 밑면으로 하는 기둥 모양, 원뿔은 밑면이 원인 뿔 모양 입체도형이에요. 구는 공처럼 중심에서 거리가 같은 점들로 이루어진 입체도형이에요. 직사각형, 직각삼각형, 반원을 한 변(지름)을 축으로 돌리면 각각 원기둥, 원뿔, 구가 돼요.\n예: 통조림 캔은 원기둥, 고깔모자는 원뿔, 축구공은 구 모양이에요."),
        ce(.elementary, "입체도형", ["전개도", "net"], "입체도형의 모서리를 잘라서 평면 위에 펼쳐 놓은 그림을 전개도라고 해요. 정육면체의 전개도는 모두 11가지예요. 원기둥의 전개도에서 옆면은 직사각형이고, 그 가로 길이는 밑면의 둘레와 같아요.\n예: 밑면의 반지름이 3 cm인 원기둥 전개도에서 옆면의 가로는 3 × 2 × 3.14 = 18.84 cm"),

        ce(.elementary, "직육면체의 부피와 겉넓이", ["직육면체의 부피", "부피", "volume"], "부피는 입체도형이 공간에서 차지하는 크기로, 한 모서리가 1 cm인 정육면체의 부피 1 cm³를 단위로 써요. 직육면체의 부피는 가로 × 세로 × 높이, 정육면체의 부피는 한 모서리를 세 번 곱한 값이에요. 1 m³ = 1000000 cm³예요.\n예: 가로 5 cm, 세로 4 cm, 높이 3 cm인 직육면체의 부피는 5 × 4 × 3 = 60 cm³"),
        ce(.elementary, "직육면체의 부피와 겉넓이", ["직육면체의 겉넓이", "겉넓이", "surface area"], "겉넓이는 입체도형의 모든 면의 넓이의 합이에요. 직육면체는 합동인 면이 2개씩 3쌍 있으므로 겉넓이 = (가로 × 세로 + 세로 × 높이 + 가로 × 높이) × 2예요. 정육면체의 겉넓이는 (한 면의 넓이) × 6이에요.\n예: 가로 5 cm, 세로 4 cm, 높이 3 cm이면 (20 + 12 + 15) × 2 = 94 cm²"),

        ce(.elementary, "규칙과 대응", ["규칙 찾기", "수의 배열", "pattern"], "수나 도형이 늘어선 모양에서 일정하게 반복되거나 변하는 규칙을 찾으면 다음에 올 것을 예상할 수 있어요. 앞뒤 수의 차이나 몇 배가 되는지 살펴보는 것이 기본이에요.\n예: 2, 5, 8, 11, …은 3씩 커지므로 다음 수는 14, 1, 2, 4, 8, …은 2배씩 커지므로 다음 수는 16"),
        ce(.elementary, "규칙과 대응", ["대응 관계", "두 양 사이의 관계", "대응 관계를 식으로 나타내기"], "한 양이 변할 때 다른 양이 일정한 규칙에 따라 함께 변하는 관계를 대응 관계라고 해요. 두 양을 □, △ 같은 기호로 나타내면 규칙을 식으로 쓸 수 있어요.\n예: 세발자전거 수를 □, 바퀴 수를 △라 하면 △ = □ × 3이에요. 자전거가 7대면 바퀴는 21개예요."),

        ce(.elementary, "자료와 그래프", ["막대그래프", "bar graph"], "조사한 자료의 수량을 막대의 길이로 나타낸 그래프예요. 항목별 크기를 한눈에 비교하기 좋아요. 가로와 세로 중 한쪽에 항목, 다른 쪽에 눈금(수량)을 나타내요.\n예: 좋아하는 과일이 사과 8명, 바나나 5명이면 사과 막대가 바나나 막대보다 3칸 길어요."),
        ce(.elementary, "자료와 그래프", ["꺾은선그래프", "line graph"], "시간에 따라 변하는 양을 점으로 찍고 선분으로 이어 나타낸 그래프예요. 늘어나고 줄어드는 변화의 흐름을 알아보기 좋고, 필요 없는 부분은 물결선으로 줄여서 그릴 수 있어요.\n예: 하루 동안 1시간마다 잰 기온을 꺾은선그래프로 그리면 기온이 가장 높은 시각과 가장 많이 오른 때를 쉽게 찾을 수 있어요."),
        ce(.elementary, "자료와 그래프", ["띠그래프와 원그래프", "비율그래프", "띠그래프", "원그래프"], "전체에 대한 각 부분의 비율을 띠 모양 직사각형으로 나타낸 것이 띠그래프, 원을 나누어 나타낸 것이 원그래프예요. 각 항목의 백분율을 구해 그 비율만큼 나누며, 백분율의 합은 100%예요.\n예: 40명 중 10명이 축구를 좋아하면 10/40 × 100 = 25%이고, 원그래프에서 원의 1/4을 차지해요."),
        ce(.elementary, "자료와 그래프", ["평균", "average", "mean"], "평균은 자료의 값을 모두 더한 뒤 자료의 수로 나눈 값으로, 자료 전체를 대표하는 값이에요. (평균) = (자료 값의 합) ÷ (자료의 수)예요.\n예: 국어 80점, 수학 90점, 영어 70점, 과학 100점의 평균은 (80 + 90 + 70 + 100) ÷ 4 = 340 ÷ 4 = 85점"),
        ce(.elementary, "자료와 그래프", ["일이 일어날 가능성", "가능성", "chance"], "어떤 일이 일어날 가능성은 '불가능하다, ~아닐 것 같다, 반반이다, ~일 것 같다, 확실하다'로 말할 수 있고, 0부터 1까지의 수로도 나타낼 수 있어요. 불가능한 일은 0, 확실한 일은 1, 반반인 일은 1/2이에요.\n예: 동전을 던져 그림 면이 나올 가능성은 1/2, 주사위를 던져 7이 나올 가능성은 0이에요."),

        // MARK: - 중학교

        ce(.middle, "소인수분해", ["소수와 합성수", "소수(素數)", "prime number", "합성수"], "1보다 큰 자연수 중에서 약수가 1과 자기 자신뿐인 수를 소수, 약수가 3개 이상인 수를 합성수라고 해요. 1은 소수도 합성수도 아니에요. 2는 유일한 짝수 소수예요.\n예: 20 이하의 소수는 2, 3, 5, 7, 11, 13, 17, 19의 8개예요."),
        ce(.middle, "소인수분해", ["거듭제곱", "지수와 밑", "power"], "같은 수를 여러 번 곱한 것을 간단히 나타낸 것을 거듭제곱이라고 해요. 곱한 수를 밑, 곱한 횟수를 지수라고 하고, 2 × 2 × 2 = 2³처럼 써요.\n예: 3 × 3 × 3 × 3 = 3⁴ = 81, 2 × 2 × 5 × 5 × 5 = 2² × 5³"),
        ce(.middle, "소인수분해", ["소인수분해", "prime factorization", "소인수"], "자연수를 소수인 인수(소인수)만의 곱으로 나타내는 것을 소인수분해라고 해요. 작은 소수부터 차례로 나누어 구하고, 결과는 거듭제곱으로 나타내요. 곱하는 순서를 무시하면 소인수분해 결과는 오직 한 가지예요. a = pᵐ × qⁿ이면 약수의 개수는 (m + 1)(n + 1)개예요.\n예: 360 = 2³ × 3² × 5이므로 약수의 개수는 (3 + 1) × (2 + 1) × (1 + 1) = 24개"),
        ce(.middle, "소인수분해", ["소인수분해를 이용한 최대공약수와 최소공배수", "최대공약수 구하기", "최소공배수 구하기", "서로소"], "각 수를 소인수분해한 뒤, 공통인 소인수에서 지수가 작은 것을 골라 곱하면 최대공약수, 모든 소인수에서 지수가 큰 것을 골라 곱하면 최소공배수가 돼요. 최대공약수가 1인 두 자연수를 서로소라고 해요.\n예: 12 = 2² × 3, 18 = 2 × 3²이면 최대공약수는 2 × 3 = 6, 최소공배수는 2² × 3² = 36"),

        ce(.middle, "정수와 유리수", ["정수", "양수와 음수", "integer"], "0보다 큰 수에는 +, 작은 수에는 −를 붙여 양수와 음수로 나타내요. 양의 정수(자연수), 0, 음의 정수를 통틀어 정수라고 해요. 수직선에서 0을 기준으로 오른쪽은 양수, 왼쪽은 음수예요.\n예: 영상 5℃는 +5℃, 영하 3℃는 −3℃, 정수는 …, −2, −1, 0, 1, 2, …"),
        ce(.middle, "정수와 유리수", ["유리수", "rational number"], "분자, 분모가 정수이고 분모가 0이 아닌 분수 a/b 꼴로 나타낼 수 있는 수를 유리수라고 해요. 정수도 2 = 2/1처럼 쓸 수 있으므로 유리수예요. 유리수는 양의 유리수, 0, 음의 유리수로 나뉘어요.\n예: −3/4, 0.5 = 1/2, 7 = 7/1은 모두 유리수예요."),
        ce(.middle, "정수와 유리수", ["절댓값", "absolute value", "|a|"], "수직선에서 어떤 수를 나타내는 점과 원점 사이의 거리를 그 수의 절댓값이라고 하고 |a|로 나타내요. 거리이므로 절댓값은 항상 0 이상이고, 0의 절댓값은 0이에요. 음수끼리는 절댓값이 큰 수가 더 작아요.\n예: |+5| = 5, |−5| = 5, |−7| > |−2|이므로 −7 < −2"),
        ce(.middle, "정수와 유리수", ["정수와 유리수의 덧셈과 뺄셈", "부호가 다른 수의 덧셈", "음수의 뺄셈"], "부호가 같은 두 수의 덧셈은 절댓값의 합에 공통인 부호를 붙이고, 부호가 다르면 절댓값의 차에 절댓값이 큰 수의 부호를 붙여요. 뺄셈은 빼는 수의 부호를 바꾸어 덧셈으로 고쳐 계산해요.\n예: (−3) + (−5) = −8, (+7) + (−10) = −3, (+4) − (−6) = (+4) + (+6) = +10"),
        ce(.middle, "정수와 유리수", ["정수와 유리수의 곱셈과 나눗셈", "부호의 규칙", "음수 곱하기 음수"], "두 수의 곱셈과 나눗셈은 절댓값끼리 계산한 뒤, 두 수의 부호가 같으면 +, 다르면 −를 붙여요. 여러 수를 곱할 때 음수가 짝수 개이면 +, 홀수 개이면 −예요. 나눗셈은 나누는 수의 역수를 곱해서 계산할 수 있어요.\n예: (−3) × (−4) = +12, (+12) ÷ (−3) = −4, (−2)³ = −8, (−2)⁴ = +16"),
        ce(.middle, "정수와 유리수", ["순환소수", "repeating decimal", "순환마디", "유한소수"], "소수점 아래에 같은 숫자의 배열이 끝없이 되풀이되는 무한소수를 순환소수, 되풀이되는 부분을 순환마디라고 해요. 기약분수의 분모를 소인수분해했을 때 소인수가 2나 5뿐이면 유한소수, 그 밖의 소인수가 있으면 순환소수가 돼요. 순환소수는 x로 놓고 10ⁿ을 곱해 빼면 분수로 바꿀 수 있어서 모두 유리수예요.\n예: 3/40 = 0.075 (40 = 2³ × 5), x = 0.2727…이면 100x − x = 27이므로 x = 27/99 = 3/11"),

        ce(.middle, "제곱근과 실수", ["제곱근", "square root", "√"], "어떤 수 x를 제곱하여 a가 될 때, x를 a의 제곱근이라고 해요. 양수 a의 제곱근은 양수 √a와 음수 −√a 두 개이고, 0의 제곱근은 0뿐이며, 음수의 제곱근은 실수 범위에서 없어요.\n예: 9의 제곱근은 3과 −3이고 √9 = 3, 5의 제곱근은 ±√5, (√7)² = 7, √((−3)²) = 3"),
        ce(.middle, "제곱근과 실수", ["무리수", "irrational number", "실수", "real number"], "순환하지 않는 무한소수로 나타나서 분수 꼴로 쓸 수 없는 수를 무리수라고 해요. 근호 안이 제곱수가 아닌 √2, √3과 원주율 π 등이 있어요. 유리수와 무리수를 통틀어 실수라고 하며, 모든 실수는 수직선 위의 한 점에 대응해요.\n예: √2 = 1.41421356…, π = 3.14159…는 무리수이고, √4 = 2는 유리수예요."),
        ce(.middle, "제곱근과 실수", ["근호를 포함한 식의 계산", "제곱근의 곱셈과 나눗셈", "분모의 유리화"], "a > 0, b > 0일 때 √a × √b = √(ab), √a ÷ √b = √(a/b), √(a²b) = a√b예요. 덧셈과 뺄셈은 근호 안이 같은 것끼리만 계산해요. 분모에 근호가 있으면 분모와 분자에 같은 근호를 곱해 분모를 유리수로 바꾸는데, 이것을 분모의 유리화라고 해요.\n예: √2 × √8 = √16 = 4, √12 = 2√3, 3√2 + 5√2 = 8√2, 1/√3 = √3/3"),

        ce(.middle, "문자와 식", ["문자를 사용한 식", "곱셈 기호의 생략", "문자식"], "수량 사이의 관계를 문자를 써서 나타내면 일반적인 식을 만들 수 있어요. 수와 문자의 곱에서는 곱셈 기호 ×를 생략하고 수를 문자 앞에 써요. 같은 문자의 곱은 거듭제곱으로, 나눗셈은 분수 꼴로 나타내요.\n예: 3 × a = 3a, a × b × a = a²b, x ÷ 4 = x/4, 한 개에 500원인 사탕 x개의 값은 500x원"),
        ce(.middle, "문자와 식", ["일차식", "항, 계수, 차수", "동류항"], "식에서 수 또는 문자의 곱으로 된 각각을 항, 문자에 곱해진 수를 계수, 수로만 된 항을 상수항이라고 해요. 차수가 1인 다항식을 일차식이라고 해요. 문자와 차수가 같은 항(동류항)끼리만 더하거나 뺄 수 있어요.\n예: 2(3x − 1) − (x + 4) = 6x − 2 − x − 4 = 5x − 6"),
        ce(.middle, "문자와 식", ["일차방정식", "linear equation", "등식의 성질", "이항"], "모든 항을 좌변으로 옮겨 정리했을 때 (일차식) = 0 꼴이 되는 방정식을 일차방정식이라고 해요. 등식의 양변에 같은 수를 더하거나 빼거나 곱하거나 0이 아닌 같은 수로 나누어도 등식은 성립해요. 항의 부호를 바꾸어 등호 반대쪽으로 옮기는 것을 이항이라고 해요.\n예: 3x + 5 = 2x − 1 → 3x − 2x = −1 − 5 → x = −6"),
        ce(.middle, "문자와 식", ["지수법칙", "laws of exponents"], "m, n이 자연수일 때 aᵐ × aⁿ = aᵐ⁺ⁿ, (aᵐ)ⁿ = aᵐⁿ, (ab)ⁿ = aⁿbⁿ이에요. a ≠ 0이면 aᵐ ÷ aⁿ은 m > n일 때 aᵐ⁻ⁿ, m = n일 때 1, m < n일 때 1/aⁿ⁻ᵐ이에요.\n예: 2³ × 2⁴ = 2⁷ = 128, (x²)³ = x⁶, x⁵ ÷ x² = x³, (2a)³ = 8a³"),
        ce(.middle, "문자와 식", ["일차부등식", "부등식의 성질", "linear inequality"], "부등호(<, >, ≤, ≥)로 수나 식의 대소 관계를 나타낸 식을 부등식이라고 해요. 양변에 같은 수를 더하거나 빼도, 양수를 곱하거나 나누어도 부등호 방향은 그대로이지만, 음수를 곱하거나 나누면 부등호 방향이 바뀌어요.\n예: −2x + 3 > 9 → −2x > 6 → x < −3"),
        ce(.middle, "문자와 식", ["연립일차방정식", "연립방정식", "가감법과 대입법", "simultaneous equations"], "미지수가 2개인 일차방정식 두 개를 한 쌍으로 묶은 것을 연립방정식이라 하고, 두 방정식을 동시에 만족하는 x, y의 값이 해예요. 한 미지수를 없애기 위해 두 식을 더하거나 빼는 가감법과, 한 식을 다른 식에 대입하는 대입법이 있어요.\n예: x + y = 5, x − y = 1을 더하면 2x = 6이므로 x = 3, y = 2"),

        ce(.middle, "다항식의 곱셈과 인수분해", ["곱셈 공식", "다항식의 곱셈", "전개"], "분배법칙으로 괄호를 풀어 하나의 다항식으로 나타내는 것을 전개라고 해요. 자주 쓰는 곱셈 공식은 (a + b)² = a² + 2ab + b², (a − b)² = a² − 2ab + b², (a + b)(a − b) = a² − b², (x + a)(x + b) = x² + (a + b)x + ab예요.\n예: (x + 3)² = x² + 6x + 9, (2x + 1)(2x − 1) = 4x² − 1, 102 × 98 = (100 + 2)(100 − 2) = 9996"),
        ce(.middle, "다항식의 곱셈과 인수분해", ["인수분해", "factorization", "공통인수", "완전제곱식"], "하나의 다항식을 두 개 이상의 다항식의 곱으로 나타내는 것을 인수분해라고 하며, 전개의 반대 과정이에요. 먼저 공통인수를 묶고, 곱셈 공식을 거꾸로 이용해요: a² + 2ab + b² = (a + b)², a² − b² = (a + b)(a − b), x² + (a + b)x + ab = (x + a)(x + b).\n예: x² − 5x + 6 = (x − 2)(x − 3), 3x² − 12 = 3(x + 2)(x − 2), 2x² + 7x + 3 = (2x + 1)(x + 3)"),

        ce(.middle, "이차방정식", ["이차방정식", "quadratic equation", "중근"], "모든 항을 좌변으로 옮겨 정리했을 때 ax² + bx + c = 0 (a ≠ 0) 꼴이 되는 방정식을 이차방정식이라고 해요. 인수분해가 되면 'AB = 0이면 A = 0 또는 B = 0'인 성질로 풀어요. 두 해가 같으면 중근이라고 해요.\n예: x² − 5x + 6 = 0 → (x − 2)(x − 3) = 0 → x = 2 또는 x = 3, x² − 6x + 9 = 0 → x = 3 (중근)"),
        ce(.middle, "이차방정식", ["근의 공식", "quadratic formula", "판별식"], "이차방정식 ax² + bx + c = 0 (a ≠ 0)의 해는 x = (−b ± √(b² − 4ac)) / (2a)예요(단, b² − 4ac ≥ 0). 완전제곱식을 만들어 유도할 수 있고, 인수분해가 어려울 때 써요. b² − 4ac > 0이면 서로 다른 두 근, = 0이면 중근, < 0이면 실수인 근이 없어요.\n예: x² + 3x − 1 = 0 → x = (−3 ± √13)/2"),

        ce(.middle, "함수", ["좌표평면", "순서쌍", "사분면"], "서로 수직인 두 수직선(x축, y축)으로 이루어진 평면을 좌표평면, 두 축이 만나는 점을 원점 O라고 해요. 평면 위의 점은 순서쌍 (x좌표, y좌표)로 나타내요. 좌표축으로 나뉜 네 부분은 제1사분면 (+, +), 제2사분면 (−, +), 제3사분면 (−, −), 제4사분면 (+, −)이에요.\n예: 점 (−2, 3)은 제2사분면 위의 점이에요."),
        ce(.middle, "함수", ["함수", "function", "함숫값"], "x의 값이 정해지면 그에 따라 y의 값이 오직 하나씩 정해지는 대응 관계가 있을 때, y를 x의 함수라고 하고 y = f(x)로 나타내요. x에 대응하는 y의 값 f(x)를 함숫값이라고 해요.\n예: f(x) = 2x + 1이면 f(3) = 7이에요. 'x의 약수 y'는 x = 6일 때 y가 여러 개이므로 함수가 아니에요."),
        ce(.middle, "함수", ["정비례와 반비례", "정비례", "반비례"], "x가 2배, 3배가 될 때 y도 2배, 3배가 되면 y는 x에 정비례한다고 하고 y = ax (a ≠ 0)로 나타내며, 그래프는 원점을 지나는 직선이에요. x가 2배, 3배가 될 때 y가 1/2배, 1/3배가 되면 반비례한다고 하고 y = a/x (a ≠ 0)이며, 그래프는 원점에 대칭인 한 쌍의 곡선이에요.\n예: 시속 60 km로 x시간 가면 거리 y = 60x, 넓이 24인 직사각형의 세로 y = 24/x"),
        ce(.middle, "함수", ["일차함수", "linear function", "기울기와 y절편"], "y = ax + b (a ≠ 0)처럼 y가 x에 대한 일차식으로 나타나는 함수를 일차함수라고 해요. 그래프는 직선이고, a는 기울기(x가 1 증가할 때 y의 증가량), b는 y절편이에요. a > 0이면 오른쪽 위로, a < 0이면 오른쪽 아래로 향해요.\n예: y = 2x − 4의 기울기는 2, y절편은 −4, x절편은 2"),
        ce(.middle, "함수", ["기울기", "slope", "직선의 방정식 구하기"], "두 점 (x₁, y₁), (x₂, y₂)를 지나는 직선의 기울기는 (y₂ − y₁)/(x₂ − x₁)이에요. 기울기 a와 한 점 (x₁, y₁)을 알면 y − y₁ = a(x − x₁)로 직선의 식을 구할 수 있어요. 기울기가 같고 y절편이 다른 두 직선은 평행해요.\n예: (1, 3), (3, 7)을 지나는 직선의 기울기는 (7 − 3)/(3 − 1) = 2이고, 식은 y = 2x + 1"),
        ce(.middle, "함수", ["일차함수와 일차방정식의 관계", "연립방정식의 해와 그래프"], "일차방정식 ax + by + c = 0 (b ≠ 0)의 그래프는 일차함수 y = −(a/b)x − c/b의 그래프와 같은 직선이에요. 연립일차방정식의 해는 두 직선의 교점의 좌표와 같아요. 두 직선이 평행하면 해가 없고, 일치하면 해가 무수히 많아요.\n예: y = x + 1과 y = −x + 3의 교점은 (1, 2)이므로 연립방정식의 해는 x = 1, y = 2"),
        ce(.middle, "함수", ["이차함수", "quadratic function", "포물선의 꼭짓점"], "y = ax² + bx + c (a ≠ 0)를 이차함수라고 하고, 그래프는 포물선이에요. a > 0이면 아래로 볼록, a < 0이면 위로 볼록하고, |a|가 클수록 폭이 좁아요. y = a(x − p)² + q 꼴로 바꾸면 꼭짓점은 (p, q), 축은 x = p이고, 이는 y = ax²을 x축 방향으로 p, y축 방향으로 q만큼 평행이동한 그래프예요.\n예: y = x² − 4x + 1 = (x − 2)² − 3이므로 꼭짓점 (2, −3), 최솟값 −3"),

        ce(.middle, "기본 도형과 작도", ["맞꼭지각", "vertical angles"], "두 직선이 한 점에서 만날 때 생기는 네 각 중 서로 마주 보는 두 각을 맞꼭지각이라고 해요. 맞꼭지각의 크기는 서로 같고, 이웃한 두 각의 크기의 합은 180°예요.\n예: 두 직선이 만나 한 각이 70°이면 그 맞꼭지각도 70°이고, 나머지 두 각은 각각 110°예요."),
        ce(.middle, "기본 도형과 작도", ["동위각과 엇각", "평행선의 성질", "동위각", "엇각"], "두 직선이 다른 한 직선과 만날 때 같은 위치에 있는 각을 동위각, 엇갈린 위치에 있는 안쪽 각을 엇각이라고 해요. 두 직선이 평행하면 동위각의 크기와 엇각의 크기가 각각 같고, 거꾸로 동위각이나 엇각의 크기가 같으면 두 직선은 평행해요.\n예: 평행한 두 직선 l, m을 직선 n이 지날 때 한 동위각이 65°이면 같은 쪽의 엇각도 65°예요."),
        ce(.middle, "기본 도형과 작도", ["작도", "construction", "삼각형의 결정 조건"], "눈금 없는 자와 컴퍼스만 사용하여 도형을 그리는 것을 작도라고 해요. 삼각형은 세 변의 길이, 두 변의 길이와 그 끼인각, 한 변의 길이와 그 양 끝 각의 크기가 주어지면 하나로 정해져요. 세 변으로 삼각형을 만들려면 가장 긴 변이 나머지 두 변의 합보다 작아야 해요.\n예: 세 변이 3, 4, 8이면 3 + 4 < 8이므로 삼각형을 만들 수 없어요."),
        ce(.middle, "기본 도형과 작도", ["삼각형의 합동 조건", "SSS 합동", "SAS 합동", "ASA 합동"], "두 삼각형은 ① 세 쌍의 대응변의 길이가 각각 같을 때(SSS), ② 두 쌍의 대응변의 길이가 같고 그 끼인각의 크기가 같을 때(SAS), ③ 한 쌍의 대응변의 길이가 같고 그 양 끝 각의 크기가 각각 같을 때(ASA) 합동이에요. 합동은 기호 ≡로 나타내요.\n예: AB = DE, BC = EF, ∠B = ∠E이면 △ABC ≡ △DEF (SAS 합동)"),

        ce(.middle, "평면도형과 입체도형", ["다각형의 내각과 외각", "다각형의 내각의 합", "외각의 합", "대각선의 개수"], "n각형의 내각의 크기의 합은 180° × (n − 2)이고, 외각의 크기의 합은 항상 360°예요. 정n각형의 한 내각은 180° × (n − 2) ÷ n, 한 외각은 360° ÷ n이에요. n각형의 대각선의 개수는 n(n − 3)/2예요.\n예: 정육각형의 내각의 합은 720°, 한 내각은 120°, 대각선은 6 × 3 ÷ 2 = 9개"),
        ce(.middle, "평면도형과 입체도형", ["부채꼴", "호의 길이와 부채꼴의 넓이", "중심각"], "원에서 두 반지름과 호로 둘러싸인 도형을 부채꼴이라고 해요. 반지름이 r, 중심각이 x°인 부채꼴의 호의 길이는 2πr × x/360, 넓이는 πr² × x/360 = (1/2) × r × (호의 길이)예요. 한 원에서 호의 길이와 부채꼴의 넓이는 중심각의 크기에 정비례해요.\n예: r = 6, 중심각 60°이면 호의 길이는 12π × 1/6 = 2π, 넓이는 36π × 1/6 = 6π"),
        ce(.middle, "평면도형과 입체도형", ["다면체", "정다면체", "polyhedron", "오일러 공식"], "다각형인 면으로만 둘러싸인 입체도형을 다면체라고 해요. 모든 면이 합동인 정다각형이고 각 꼭짓점에 모인 면의 개수가 같은 볼록한 다면체를 정다면체라 하며, 정사면체·정육면체·정팔면체·정십이면체·정이십면체의 5가지뿐이에요. 볼록한 다면체에서 (꼭짓점) − (모서리) + (면) = 2예요.\n예: 정팔면체는 6 − 12 + 8 = 2"),
        ce(.middle, "평면도형과 입체도형", ["기둥의 겉넓이와 부피", "원기둥의 부피", "원기둥의 겉넓이"], "기둥의 부피는 (밑넓이) × (높이), 겉넓이는 (밑넓이) × 2 + (옆넓이)예요. 반지름 r, 높이 h인 원기둥의 부피는 πr²h, 겉넓이는 2πr² + 2πrh예요.\n예: r = 3, h = 5인 원기둥의 부피는 π × 9 × 5 = 45π, 겉넓이는 18π + 30π = 48π"),
        ce(.middle, "평면도형과 입체도형", ["뿔과 구의 겉넓이와 부피", "원뿔의 부피", "구의 부피", "구의 겉넓이"], "뿔의 부피는 밑면과 높이가 같은 기둥 부피의 1/3이므로 원뿔의 부피는 (1/3)πr²h예요. 반지름 r인 구의 겉넓이는 4πr², 부피는 (4/3)πr³이에요.\n예: r = 3, h = 4인 원뿔의 부피는 (1/3) × π × 9 × 4 = 12π, 반지름 3인 구의 겉넓이는 36π, 부피는 (4/3)π × 27 = 36π"),

        ce(.middle, "도형의 성질과 닮음", ["이등변삼각형의 성질", "isosceles triangle"], "두 변의 길이가 같은 삼각형을 이등변삼각형이라고 해요. 이등변삼각형의 두 밑각의 크기는 같고, 꼭지각의 이등분선은 밑변을 수직이등분해요. 거꾸로 두 내각의 크기가 같은 삼각형은 이등변삼각형이에요.\n예: AB = AC이고 ∠A = 50°이면 ∠B = ∠C = (180° − 50°) ÷ 2 = 65°"),
        ce(.middle, "도형의 성질과 닮음", ["삼각형의 외심과 내심", "외심", "내심"], "세 변의 수직이등분선의 교점이 외심으로, 외심에서 세 꼭짓점까지의 거리가 같아 외접원의 중심이 돼요. 세 내각의 이등분선의 교점이 내심으로, 내심에서 세 변까지의 거리가 같아 내접원의 중심이 돼요. 직각삼각형의 외심은 빗변의 중점이고, 삼각형의 넓이 = (1/2) × (내접원의 반지름) × (세 변의 길이의 합)이에요.\n예: 세 변이 3, 4, 5인 직각삼각형의 외접원 반지름은 2.5, 넓이 6 = (1/2) × r × 12이므로 내접원 반지름은 1"),
        ce(.middle, "도형의 성질과 닮음", ["평행사변형의 성질", "parallelogram", "직사각형과 마름모의 대각선"], "두 쌍의 대변이 각각 평행한 사각형을 평행사변형이라고 해요. 평행사변형은 두 쌍의 대변의 길이와 두 쌍의 대각의 크기가 각각 같고, 두 대각선이 서로를 이등분해요. 직사각형은 두 대각선의 길이가 같고, 마름모는 두 대각선이 서로를 수직이등분해요.\n예: 평행사변형 ABCD에서 ∠A = 110°이면 ∠C = 110°, ∠B = ∠D = 70°"),
        ce(.middle, "도형의 성질과 닮음", ["도형의 닮음", "닮음비", "similarity"], "한 도형을 일정한 비율로 확대하거나 축소하여 다른 도형과 합동이 될 때 두 도형은 닮음이라 하고 기호 ∽로 나타내요. 대응변의 길이의 비를 닮음비라고 해요. 닮음비가 m : n이면 넓이의 비는 m² : n², 부피의 비는 m³ : n³이에요.\n예: 닮음비가 2 : 3인 두 삼각형의 넓이의 비는 4 : 9, 닮음비가 2 : 3인 두 입체도형의 부피의 비는 8 : 27"),
        ce(.middle, "도형의 성질과 닮음", ["삼각형의 닮음 조건", "SSS 닮음", "SAS 닮음", "AA 닮음"], "두 삼각형은 ① 세 쌍의 대응변의 길이의 비가 같을 때(SSS 닮음), ② 두 쌍의 대응변의 길이의 비가 같고 그 끼인각의 크기가 같을 때(SAS 닮음), ③ 두 쌍의 대응각의 크기가 각각 같을 때(AA 닮음) 닮음이에요.\n예: ∠A = 90°인 직각삼각형 ABC에서 A에서 빗변에 내린 수선의 발을 H라 하면 △ABC ∽ △HBA (AA 닮음)이므로 AB² = BH × BC예요."),
        ce(.middle, "도형의 성질과 닮음", ["삼각형의 무게중심", "무게중심", "중선", "중점연결정리"], "삼각형의 꼭짓점과 마주 보는 변의 중점을 이은 선분을 중선이라 하고, 세 중선이 만나는 점이 무게중심이에요. 무게중심은 각 중선을 꼭짓점으로부터 2 : 1로 나누어요. 또 두 변의 중점을 이은 선분은 나머지 변과 평행하고 길이가 그 1/2이에요(중점연결정리).\n예: 중선 AD의 길이가 9이면 무게중심 G에 대해 AG = 6, GD = 3"),
        ce(.middle, "도형의 성질과 닮음", ["피타고라스 정리", "Pythagorean theorem"], "직각삼각형에서 직각을 낀 두 변의 길이를 a, b, 빗변의 길이를 c라고 하면 a² + b² = c²이 성립해요. 거꾸로 세 변의 길이가 a² + b² = c²을 만족하면 빗변이 c인 직각삼각형이에요.\n예: 두 변이 6, 8인 직각삼각형의 빗변은 √(36 + 64) = 10, 한 변이 1인 정사각형의 대각선은 √2"),
        ce(.middle, "도형의 성질과 닮음", ["원주각", "inscribed angle", "원주각의 성질", "원에 내접하는 사각형"], "원 위의 한 점에서 그은 두 현이 이루는 각을 원주각이라고 해요. 한 호에 대한 원주각의 크기는 중심각의 크기의 1/2이고, 같은 호에 대한 원주각은 모두 같으며, 지름에 대한 원주각은 90°예요. 원에 내접하는 사각형에서 마주 보는 두 각의 합은 180°예요.\n예: 호 AB에 대한 중심각이 100°이면 원주각은 50°예요."),
        ce(.middle, "도형의 성질과 닮음", ["원의 접선", "접선의 길이", "원과 현"], "원의 접선은 접점을 지나는 반지름과 수직이에요. 원 밖의 한 점에서 원에 그은 두 접선의 길이는 같아요. 원의 중심에서 현에 내린 수선은 그 현을 이등분하고, 중심에서 같은 거리에 있는 두 현의 길이는 같아요.\n예: 반지름 5인 원의 중심에서 거리가 3인 현의 길이는 2 × √(25 − 9) = 8"),

        ce(.middle, "삼각비", ["삼각비", "sin, cos, tan", "trigonometric ratio"], "∠C = 90°인 직각삼각형 ABC에서 세 변을 a = BC, b = CA, c = AB(빗변)라 하면 ∠A의 삼각비는 sin A = a/c, cos A = b/c, tan A = a/b예요. 삼각비의 값은 삼각형의 크기와 상관없이 각의 크기에 따라 정해져요.\n예: 세 변이 3, 4, 5이고 ∠A의 대변이 3이면 sin A = 3/5, cos A = 4/5, tan A = 3/4"),
        ce(.middle, "삼각비", ["특수각의 삼각비", "30°, 45°, 60°의 삼각비", "삼각비의 활용"], "sin 30° = 1/2, cos 30° = √3/2, tan 30° = √3/3, sin 45° = cos 45° = √2/2, tan 45° = 1, sin 60° = √3/2, cos 60° = 1/2, tan 60° = √3이에요. 두 변 a, b와 끼인각 θ (예각)를 알면 삼각형의 넓이는 (1/2)ab sin θ예요.\n예: 빗변이 10이고 한 예각이 30°이면 그 각의 대변은 10 × sin 30° = 5, 두 변 6, 8과 끼인각 30°인 삼각형의 넓이는 12"),

        ce(.middle, "확률과 통계", ["도수분포표와 히스토그램", "도수분포표", "히스토그램", "상대도수"], "자료를 몇 개의 계급(구간)으로 나누고 각 계급에 속하는 자료의 개수(도수)를 나타낸 표를 도수분포표라고 해요. 이를 직사각형 기둥으로 나타낸 그래프가 히스토그램이에요. 상대도수 = (그 계급의 도수) ÷ (도수의 총합)이고, 상대도수의 합은 1이에요.\n예: 30명 중 60점 이상 70점 미만이 6명이면 그 계급의 상대도수는 6/30 = 0.2"),
        ce(.middle, "확률과 통계", ["경우의 수", "합의 법칙과 곱의 법칙"], "어떤 사건이 일어나는 가짓수를 경우의 수라고 해요. 두 사건 A, B가 동시에 일어나지 않을 때 A 또는 B가 일어나는 경우의 수는 m + n(합의 법칙), A와 B가 동시에 일어나는 경우의 수는 m × n(곱의 법칙)이에요.\n예: 주사위 1개를 던져 2 이하 또는 5 이상의 눈이 나오는 경우는 2 + 2 = 4가지, 동전 1개와 주사위 1개를 던지는 경우는 2 × 6 = 12가지"),
        ce(.middle, "확률과 통계", ["확률", "probability", "확률의 성질"], "각 경우가 일어날 가능성이 같을 때 사건 A가 일어날 확률은 (A가 일어나는 경우의 수) ÷ (모든 경우의 수)예요. 확률 p는 0 ≤ p ≤ 1이고, A가 일어나지 않을 확률은 1 − p예요. 두 사건이 서로 영향을 주지 않으면 동시에 일어날 확률은 두 확률의 곱이에요.\n예: 주사위에서 3의 배수가 나올 확률은 2/6 = 1/3, 동전 2개를 던져 적어도 한 개가 앞면일 확률은 1 − 1/4 = 3/4"),
        ce(.middle, "확률과 통계", ["대푯값", "평균, 중앙값, 최빈값", "중앙값", "최빈값"], "자료 전체의 특징을 하나의 수로 나타낸 값을 대푯값이라고 하며 평균, 중앙값, 최빈값이 있어요. 중앙값은 크기순으로 나열했을 때 가운데 값(자료 수가 짝수면 가운데 두 값의 평균), 최빈값은 가장 많이 나타나는 값이에요. 극단적인 값이 있으면 평균보다 중앙값이 적절해요.\n예: 2, 3, 3, 5, 7, 10의 평균은 5, 중앙값은 (3 + 5)/2 = 4, 최빈값은 3"),
        ce(.middle, "확률과 통계", ["산포도", "분산과 표준편차", "편차"], "자료가 흩어져 있는 정도를 산포도라고 해요. 편차 = (자료의 값) − (평균)이고 편차의 합은 항상 0이에요. 분산은 편차의 제곱의 평균, 표준편차는 분산의 음이 아닌 제곱근이에요. 표준편차가 작을수록 자료가 평균 가까이 모여 있어요.\n예: 4, 6, 8의 평균은 6, 편차는 −2, 0, 2, 분산은 (4 + 0 + 4)/3 = 8/3, 표준편차는 √(8/3) = 2√6/3"),
        ce(.middle, "확률과 통계", ["산점도와 상관관계", "상관관계", "산점도"], "두 변량의 순서쌍을 좌표평면 위에 점으로 나타낸 그래프를 산점도라고 해요. 한 변량이 커질 때 다른 변량도 대체로 커지면 양의 상관관계, 대체로 작아지면 음의 상관관계, 뚜렷한 경향이 없으면 상관관계가 없다고 해요. 점들이 한 직선 가까이 모일수록 상관관계가 강해요.\n예: 키와 몸무게는 양의 상관관계, 산의 높이와 기온은 음의 상관관계예요."),

        // MARK: - 고등학교

        ce(.high, "지수함수와 로그함수", ["지수의 확장", "거듭제곱근", "유리수 지수", "음의 지수"], "n제곱하여 a가 되는 수를 a의 n제곱근이라 하고, a > 0일 때 그중 양의 실수를 ⁿ√a로 써요. a > 0이면 a⁰ = 1, a⁻ⁿ = 1/aⁿ, a^(m/n) = ⁿ√(aᵐ)으로 정의하며, 이렇게 확장해도 지수법칙 aˣaʸ = aˣ⁺ʸ, (aˣ)ʸ = aˣʸ가 그대로 성립해요.\n예: ³√8 = 2, 2⁻³ = 1/8, 8^(2/3) = (³√8)² = 4, 27^(−1/3) = 1/3"),
        ce(.high, "지수함수와 로그함수", ["로그", "logarithm", "log", "상용로그"], "a > 0, a ≠ 1, N > 0일 때 aˣ = N을 만족하는 x를 a를 밑으로 하는 N의 로그라 하고 x = logₐN으로 써요. N을 진수라고 해요. 밑이 10인 로그를 상용로그라 하고 밑을 생략해 log N으로 써요.\n예: log₂8 = 3 (2³ = 8), log₃(1/9) = −2, log 1000 = 3, log 2 ≈ 0.3010이므로 log 2³⁰ ≈ 9.03이고 2³⁰은 10자리 수예요."),
        ce(.high, "지수함수와 로그함수", ["로그의 성질", "밑 변환 공식", "로그 법칙"], "a > 0, a ≠ 1, M > 0, N > 0일 때 logₐ1 = 0, logₐa = 1, logₐMN = logₐM + logₐN, logₐ(M/N) = logₐM − logₐN, logₐMᵏ = k logₐM이에요. 밑 변환 공식은 logₐb = (log b)/(log a)로, 분모와 분자의 로그는 같은 밑이면 어떤 밑이든 돼요.\n예: log₂12 − log₂3 = log₂4 = 2, log₄8 = (log₂8)/(log₂4) = 3/2"),
        ce(.high, "지수함수와 로그함수", ["지수함수", "exponential function", "y = aˣ"], "a > 0, a ≠ 1일 때 y = aˣ을 지수함수라고 해요. 정의역은 실수 전체, 치역은 양의 실수 전체이고, 그래프는 점 (0, 1)을 지나며 x축이 점근선이에요. a > 1이면 증가함수, 0 < a < 1이면 감소함수예요.\n예: 2ˣ = 32 → 2ˣ = 2⁵ → x = 5, (1/2)ˣ > 1/8 = (1/2)³ → 감소함수이므로 x < 3"),
        ce(.high, "지수함수와 로그함수", ["로그함수", "logarithmic function", "y = logₐx"], "a > 0, a ≠ 1일 때 y = logₐx를 로그함수라고 하며, 지수함수 y = aˣ의 역함수예요. 정의역은 양의 실수 전체, 치역은 실수 전체이고, 그래프는 점 (1, 0)을 지나며 y축이 점근선이에요. y = aˣ의 그래프와 직선 y = x에 대하여 대칭이에요.\n예: log₂(x − 1) = 3 → x − 1 = 8 → x = 9, log₃x < 2 → 0 < x < 9"),

        ce(.high, "삼각함수", ["호도법", "라디안", "radian"], "반지름의 길이와 같은 길이의 호에 대한 중심각의 크기를 1라디안이라 하고, 이렇게 각을 나타내는 방법을 호도법이라고 해요. 180° = π (라디안)이므로 1라디안 ≈ 57.3°예요. 반지름 r, 중심각 θ인 부채꼴의 호의 길이는 l = rθ, 넓이는 S = (1/2)r²θ예요.\n예: 60° = π/3, 반지름 6, 중심각 π/3인 부채꼴의 호의 길이는 2π, 넓이는 6π"),
        ce(.high, "삼각함수", ["삼각함수", "trigonometric function", "일반각"], "원점을 중심으로 하는 반지름 r인 원 위의 점 P(x, y)에 대해 동경 OP가 x축의 양의 방향과 이루는 각을 θ라 하면 sin θ = y/r, cos θ = x/r, tan θ = y/x (x ≠ 0)예요. 부호는 제1사분면에서 모두 +, 제2사분면은 sin만 +, 제3사분면은 tan만 +, 제4사분면은 cos만 +예요.\n예: θ = 2π/3이면 sin θ = √3/2, cos θ = −1/2, tan θ = −√3"),
        ce(.high, "삼각함수", ["삼각함수 사이의 관계", "sin²θ + cos²θ = 1"], "모든 θ에 대해 sin²θ + cos²θ = 1이고, tan θ = sin θ / cos θ예요. 또 sin(−θ) = −sin θ, cos(−θ) = cos θ, sin(π/2 − θ) = cos θ, sin(π − θ) = sin θ, cos(π − θ) = −cos θ가 성립해요.\n예: θ가 제2사분면의 각이고 sin θ = 3/5이면 cos θ = −√(1 − 9/25) = −4/5, tan θ = −3/4"),
        ce(.high, "삼각함수", ["삼각함수의 그래프", "주기", "최댓값과 최솟값 (삼각함수)"], "y = sin x, y = cos x는 주기가 2π이고 치역이 −1 ≤ y ≤ 1인 물결 모양 그래프예요. y = tan x는 주기가 π이고 x = π/2 + nπ (n은 정수)에서 점근선을 가져요. y = a sin(bx + c) + d의 최댓값은 |a| + d, 최솟값은 −|a| + d, 주기는 2π/|b|예요.\n예: y = 3 sin 2x + 1의 주기는 π, 최댓값 4, 최솟값 −2"),
        ce(.high, "삼각함수", ["사인법칙", "law of sines"], "삼각형 ABC의 외접원의 반지름을 R이라 하면 a/sin A = b/sin B = c/sin C = 2R이 성립해요. 한 변과 두 각을 알 때 나머지 변을 구하거나, 외접원의 반지름을 구할 때 써요.\n예: a = 6, A = 30°이면 2R = 6 ÷ (1/2) = 12이므로 R = 6이에요."),
        ce(.high, "삼각함수", ["코사인법칙", "law of cosines"], "삼각형 ABC에서 a² = b² + c² − 2bc cos A가 성립해요(b², c²도 같은 꼴). 두 변과 그 끼인각을 알 때 나머지 변을 구하거나, 세 변을 알 때 cos A = (b² + c² − a²)/(2bc)로 각을 구해요. A = 90°이면 피타고라스 정리가 돼요.\n예: b = 3, c = 5, A = 120°이면 a² = 9 + 25 − 2 × 3 × 5 × (−1/2) = 49, a = 7"),

        ce(.high, "수열", ["수열", "sequence", "일반항"], "차례로 나열된 수의 열을 수열이라 하고, 각 수를 항이라고 해요. n번째 항 aₙ을 n에 대한 식으로 나타낸 것을 일반항이라고 해요. 수열은 자연수 n에 aₙ을 대응시키는 함수로 볼 수 있어요. 첫째항부터 제n항까지의 합을 Sₙ이라 하면 a₁ = S₁, n ≥ 2일 때 aₙ = Sₙ − Sₙ₋₁이에요.\n예: 1, 4, 9, 16, …의 일반항은 aₙ = n²이므로 a₁₀ = 100"),
        ce(.high, "수열", ["등차수열", "arithmetic sequence", "공차"], "첫째항부터 차례로 일정한 수 d를 더해 만든 수열을 등차수열, d를 공차라고 해요. 첫째항 a, 공차 d인 등차수열의 일반항은 aₙ = a + (n − 1)d이고, 첫째항부터 제n항까지의 합은 Sₙ = n{2a + (n − 1)d}/2 = n(a + l)/2 (l은 끝항)예요.\n예: 3, 7, 11, …에서 a₁₀ = 3 + 9 × 4 = 39, S₁₀ = 10 × (3 + 39)/2 = 210"),
        ce(.high, "수열", ["등비수열", "geometric sequence", "공비"], "첫째항부터 차례로 0이 아닌 일정한 수 r을 곱해 만든 수열을 등비수열, r을 공비라고 해요. 일반항은 aₙ = arⁿ⁻¹이고, 합은 r ≠ 1일 때 Sₙ = a(rⁿ − 1)/(r − 1), r = 1일 때 Sₙ = na예요.\n예: 2, 6, 18, …에서 a₅ = 2 × 3⁴ = 162, S₅ = 2(3⁵ − 1)/(3 − 1) = 242"),
        ce(.high, "수열", ["합의 기호 Σ", "시그마", "Σ", "자연수의 거듭제곱의 합"], "수열의 합 a₁ + a₂ + … + aₙ을 기호 Σ를 써서 Σₖ₌₁ⁿ aₖ로 나타내요. Σ(aₖ + bₖ) = Σaₖ + Σbₖ, Σcaₖ = cΣaₖ이고, Σk = n(n + 1)/2, Σk² = n(n + 1)(2n + 1)/6, Σk³ = {n(n + 1)/2}²을 자주 써요(k = 1부터 n까지).\n예: 1² + 2² + … + 10² = 10 × 11 × 21 / 6 = 385"),
        ce(.high, "수열", ["수학적 귀납법", "mathematical induction", "점화식"], "모든 자연수 n에 대해 명제 p(n)이 참임을 보이려면 ① n = 1일 때 성립함을 보이고, ② n = k일 때 성립한다고 가정하면 n = k + 1일 때도 성립함을 보이면 돼요. 도미노가 차례로 쓰러지는 원리와 같아요.\n예: 1 + 2 + … + n = n(n + 1)/2가 n = k일 때 성립하면 양변에 k + 1을 더해 k(k + 1)/2 + (k + 1) = (k + 1)(k + 2)/2이므로 n = k + 1일 때도 성립해요."),

        ce(.high, "수열의 극한", ["수열의 극한", "수렴과 발산", "limit of a sequence"], "n이 한없이 커질 때 aₙ이 일정한 값 α에 한없이 가까워지면 수열이 α에 수렴한다고 하고 lim(n→∞) aₙ = α로 써요. 수렴하지 않으면 발산한다고 해요. 분수 꼴은 분모의 최고차항으로 분자와 분모를 나누어 계산해요. 등비수열 rⁿ은 −1 < r < 1이면 0, r = 1이면 1에 수렴하고 그 밖에는 발산해요.\n예: lim(n→∞) (3n² + 1)/(n² − 2n) = 3, (−1)ⁿ은 진동(발산)"),
        ce(.high, "수열의 극한", ["급수", "series", "부분합"], "수열의 모든 항을 더한 a₁ + a₂ + a₃ + …을 급수라 하고, 부분합 Sₙ = a₁ + … + aₙ이 S에 수렴하면 급수의 합이 S라고 해요. 급수 Σaₙ이 수렴하면 lim aₙ = 0이지만, 거꾸로는 성립하지 않아요.\n예: Σ 1/(n(n + 1)) = Σ (1/n − 1/(n + 1))의 부분합은 1 − 1/(n + 1) → 1, 조화급수 Σ 1/n은 aₙ → 0이지만 발산해요."),
        ce(.high, "수열의 극한", ["등비급수", "geometric series", "무한등비급수"], "첫째항 a (a ≠ 0), 공비 r인 등비급수 a + ar + ar² + …은 −1 < r < 1일 때 수렴하고 그 합은 a/(1 − r)이에요. r ≤ −1 또는 r ≥ 1이면 발산해요.\n예: 1 + 1/2 + 1/4 + … = 1/(1 − 1/2) = 2, 0.333… = 0.3 + 0.03 + … = 0.3/(1 − 0.1) = 1/3"),

        ce(.high, "함수의 극한과 연속", ["함수의 극한", "limit", "좌극한과 우극한"], "x가 a가 아니면서 a에 한없이 가까워질 때 f(x)가 L에 한없이 가까워지면 lim(x→a) f(x) = L이라고 써요. 극한값이 존재하려면 좌극한과 우극한이 모두 존재하고 같아야 해요. 0/0 꼴은 인수분해나 유리화로 약분해서 구해요.\n예: lim(x→2) (x² − 4)/(x − 2) = lim(x→2) (x + 2) = 4"),
        ce(.high, "함수의 극한과 연속", ["함수의 연속", "continuity", "연속함수", "사잇값 정리"], "f(x)가 x = a에서 정의되고, 극한 lim(x→a) f(x)가 존재하며, 그 값이 f(a)와 같으면 x = a에서 연속이에요. 다항함수는 모든 실수에서 연속이에요. 닫힌구간 [a, b]에서 연속이고 f(a)f(b) < 0이면 f(x) = 0인 x가 a와 b 사이에 적어도 하나 있어요(사잇값 정리).\n예: x³ + x − 1 = 0은 f(0) = −1, f(1) = 1이므로 0과 1 사이에 실근이 있어요."),

        ce(.high, "미분", ["미분계수", "평균변화율", "순간변화율"], "x가 a에서 b까지 변할 때 평균변화율은 (f(b) − f(a))/(b − a)예요. 극한 f′(a) = lim(h→0) (f(a + h) − f(a))/h를 x = a에서의 미분계수(순간변화율)라 하고, 이는 곡선 y = f(x) 위의 점 (a, f(a))에서의 접선의 기울기예요.\n예: f(x) = x²이면 f′(3) = lim(h→0) ((3 + h)² − 9)/h = lim(h→0) (6 + h) = 6"),
        ce(.high, "미분", ["도함수", "derivative", "미분법 공식", "곱의 미분법"], "각 x에 미분계수 f′(x)를 대응시킨 함수를 도함수라고 해요. (xⁿ)′ = nxⁿ⁻¹, (상수)′ = 0, {f(x) ± g(x)}′ = f′(x) ± g′(x), {f(x)g(x)}′ = f′(x)g(x) + f(x)g′(x), {f(x)/g(x)}′ = {f′(x)g(x) − f(x)g′(x)}/{g(x)}²예요. 미분가능하면 연속이지만 역은 성립하지 않아요.\n예: (x³ − 4x² + 5)′ = 3x² − 8x, y = |x|는 x = 0에서 연속이지만 미분가능하지 않아요."),
        ce(.high, "미분", ["접선의 방정식", "tangent line"], "곡선 y = f(x) 위의 점 (a, f(a))에서의 접선은 기울기가 f′(a)이므로 방정식은 y − f(a) = f′(a)(x − a)예요. 기울기가 주어지면 f′(t) = (기울기)인 접점의 x좌표 t를 먼저 구해요.\n예: y = x² + 1 위의 점 (1, 2)에서 f′(1) = 2이므로 접선은 y − 2 = 2(x − 1), 즉 y = 2x"),
        ce(.high, "미분", ["함수의 증가와 감소", "증가함수와 감소함수", "증감표"], "어떤 구간에서 f′(x) > 0이면 f(x)는 그 구간에서 증가하고, f′(x) < 0이면 감소해요. 도함수의 부호를 표(증감표)로 정리하면 그래프의 개형을 알 수 있어요.\n예: f(x) = x³ − 3x이면 f′(x) = 3(x + 1)(x − 1)이므로 x < −1 또는 x > 1에서 증가, −1 < x < 1에서 감소해요."),
        ce(.high, "미분", ["극대와 극소", "극값", "extremum", "최댓값과 최솟값"], "f′(x)의 부호가 x = a의 좌우에서 +에서 −로 바뀌면 f(a)는 극댓값, −에서 +로 바뀌면 극솟값이에요. f′(a) = 0이라고 반드시 극값인 것은 아니에요. 닫힌구간의 최댓값·최솟값은 극값과 양 끝 값을 비교해서 구해요.\n예: f(x) = x³ − 3x는 x = −1에서 극댓값 2, x = 1에서 극솟값 −2를 가져요. f(x) = x³은 f′(0) = 0이지만 극값이 없어요."),
        ce(.high, "미분", ["지수함수와 로그함수의 미분", "eˣ의 미분", "자연로그"], "lim(x→0) (1 + x)^(1/x) = e (≈ 2.718)이고, 밑이 e인 로그를 자연로그 ln x라고 해요. (eˣ)′ = eˣ, (aˣ)′ = aˣ ln a, (ln x)′ = 1/x, (logₐx)′ = 1/(x ln a)예요.\n예: (x eˣ)′ = eˣ + x eˣ = (x + 1)eˣ, (ln(x² + 1))′ = 2x/(x² + 1)"),
        ce(.high, "미분", ["삼각함수의 미분", "sin x의 미분", "lim sin x / x"], "x를 라디안으로 잴 때 lim(x→0) sin x / x = 1이고, 이를 이용하면 (sin x)′ = cos x, (cos x)′ = −sin x를 얻어요. 몫의 미분법으로 (tan x)′ = 1/cos²x = sec²x예요.\n예: (sin 3x)′ = 3 cos 3x, lim(x→0) sin 5x / x = 5"),
        ce(.high, "미분", ["합성함수의 미분법", "연쇄법칙", "chain rule"], "y = f(u), u = g(x)일 때 dy/dx = (dy/du) × (du/dx), 즉 {f(g(x))}′ = f′(g(x)) × g′(x)예요. '겉함수를 미분하고 속함수의 미분을 곱한다'고 기억하면 쉬워요.\n예: y = (2x + 1)⁵이면 y′ = 5(2x + 1)⁴ × 2 = 10(2x + 1)⁴, y = sin(x²)이면 y′ = 2x cos(x²)"),
        ce(.high, "미분", ["음함수의 미분법", "implicit differentiation", "매개변수로 나타낸 함수의 미분"], "x, y의 관계가 f(x, y) = 0 꼴로 주어지면 y를 x의 함수로 보고 양변을 x에 대해 미분한 뒤 dy/dx에 대해 풀어요. y가 들어간 항은 합성함수의 미분법에 따라 dy/dx를 곱해요. x = f(t), y = g(t)이면 dy/dx = g′(t)/f′(t)예요.\n예: x² + y² = 25를 미분하면 2x + 2y(dy/dx) = 0 → dy/dx = −x/y, 점 (3, 4)에서 접선의 기울기는 −3/4"),
        ce(.high, "미분", ["이계도함수와 변곡점", "변곡점", "오목과 볼록"], "f′(x)를 한 번 더 미분한 f″(x)를 이계도함수라고 해요. f″(x) > 0인 구간에서 곡선은 아래로 볼록, f″(x) < 0이면 위로 볼록해요. 볼록한 방향이 바뀌는 점을 변곡점이라 하며, f″(a) = 0이고 그 좌우에서 f″(x)의 부호가 바뀌면 (a, f(a))는 변곡점이에요.\n예: f(x) = x³ − 3x²이면 f″(x) = 6x − 6이므로 변곡점은 (1, −2)"),

        ce(.high, "적분", ["부정적분", "antiderivative", "적분상수"], "F′(x) = f(x)일 때 F(x)를 f(x)의 부정적분이라 하고 ∫f(x)dx = F(x) + C (C는 적분상수)로 써요. n ≠ −1이면 ∫xⁿdx = xⁿ⁺¹/(n + 1) + C이고, ∫(1/x)dx = ln|x| + C, ∫eˣdx = eˣ + C, ∫cos x dx = sin x + C예요.\n예: ∫(3x² − 4x + 1)dx = x³ − 2x² + x + C"),
        ce(.high, "적분", ["정적분", "definite integral", "미적분의 기본정리"], "f(x)가 [a, b]에서 연속이고 F(x)가 f(x)의 한 부정적분이면 ∫ₐᵇ f(x)dx = F(b) − F(a)예요(미적분의 기본정리). 정적분은 잘게 나눈 직사각형 넓이의 합의 극한(구분구적법)과 같아요. 또 d/dx ∫ₐˣ f(t)dt = f(x)예요.\n예: ∫₀² (x² + 1)dx = [x³/3 + x]₀² = 8/3 + 2 = 14/3"),
        ce(.high, "적분", ["정적분과 넓이", "곡선과 x축 사이의 넓이", "두 곡선 사이의 넓이"], "곡선 y = f(x)와 x축, 두 직선 x = a, x = b로 둘러싸인 넓이는 ∫ₐᵇ |f(x)|dx예요. 두 곡선 y = f(x), y = g(x) 사이의 넓이는 ∫ₐᵇ |f(x) − g(x)|dx이며, 위쪽 함수에서 아래쪽 함수를 빼서 적분해요.\n예: y = x²과 y = x로 둘러싸인 넓이는 ∫₀¹ (x − x²)dx = 1/2 − 1/3 = 1/6"),
        ce(.high, "적분", ["치환적분법", "치환적분", "integration by substitution"], "합성함수 꼴의 적분은 g(x) = t로 치환하면 ∫f(g(x))g′(x)dx = ∫f(t)dt가 돼요. 정적분에서는 적분 구간도 t의 범위로 바꿔야 해요. 특히 ∫f′(x)/f(x) dx = ln|f(x)| + C예요.\n예: ∫2x(x² + 1)³dx에서 x² + 1 = t로 놓으면 ∫t³dt = t⁴/4 + C = (x² + 1)⁴/4 + C"),
        ce(.high, "적분", ["부분적분법", "부분적분", "integration by parts"], "곱의 미분법을 거꾸로 이용한 ∫f(x)g′(x)dx = f(x)g(x) − ∫f′(x)g(x)dx를 부분적분법이라고 해요. 보통 미분하면 간단해지는 쪽(다항식, 로그)을 f(x)로, 적분하기 쉬운 쪽(지수, 삼각함수)을 g′(x)로 잡아요.\n예: ∫x eˣdx = x eˣ − ∫eˣdx = (x − 1)eˣ + C, ∫ln x dx = x ln x − x + C"),

        ce(.high, "경우의 수", ["순열", "permutation", "nPr", "팩토리얼"], "서로 다른 n개에서 r개를 택해 일렬로 나열하는 경우의 수를 순열이라 하고 ₙPᵣ로 나타내요. ₙPᵣ = n(n − 1)(n − 2)…(n − r + 1) = n!/(n − r)!이고, n! = n × (n − 1) × … × 1, 0! = 1이에요. 서로 다른 n개를 원형으로 배열하는 원순열의 수는 (n − 1)!이에요.\n예: 5명 중 반장, 부반장, 서기를 뽑는 경우의 수는 ₅P₃ = 5 × 4 × 3 = 60"),
        ce(.high, "경우의 수", ["중복순열과 같은 것이 있는 순열", "중복순열", "같은 것이 있는 순열"], "서로 다른 n개에서 중복을 허락하여 r개를 택해 일렬로 나열하는 경우의 수(중복순열)는 nʳ이에요. n개 중 같은 것이 각각 p개, q개, r개 있을 때 n개를 일렬로 나열하는 경우의 수는 n!/(p!q!r!)이에요(p + q + r = n).\n예: 숫자 1, 2, 3으로 중복을 허락해 만드는 네 자리 수는 3⁴ = 81개, banana의 문자를 나열하는 경우의 수는 6!/(3!2!) = 60"),
        ce(.high, "경우의 수", ["조합", "combination", "nCr", "중복조합"], "서로 다른 n개에서 순서를 생각하지 않고 r개를 택하는 경우의 수를 ₙCᵣ로 나타내고 ₙCᵣ = n!/(r!(n − r)!)이에요. ₙCᵣ = ₙCₙ₋ᵣ이 성립해요. 중복을 허락해 택하는 중복조합은 ₙHᵣ = ₙ₊ᵣ₋₁Cᵣ예요.\n예: 10명 중 대표 3명을 뽑는 경우의 수는 ₁₀C₃ = (10 × 9 × 8)/(3 × 2 × 1) = 120, x + y + z = 5의 음이 아닌 정수해는 ₃H₅ = ₇C₅ = 21개"),
        ce(.high, "경우의 수", ["이항정리", "binomial theorem", "파스칼의 삼각형", "이항계수"], "(a + b)ⁿ = ₙC₀aⁿ + ₙC₁aⁿ⁻¹b + … + ₙCᵣaⁿ⁻ʳbʳ + … + ₙCₙbⁿ이에요. 일반항은 ₙCᵣaⁿ⁻ʳbʳ이고, 계수 ₙCᵣ를 이항계수라고 해요. 이항계수를 삼각형 모양으로 배열한 것이 파스칼의 삼각형이고, ₙC₀ + ₙC₁ + … + ₙCₙ = 2ⁿ이에요.\n예: (x + 2)⁵에서 x³의 계수는 ₅C₂ × 2² = 10 × 4 = 40"),

        ce(.high, "확률", ["확률의 덧셈정리", "여사건의 확률", "배반사건"], "두 사건 A, B에 대해 P(A ∪ B) = P(A) + P(B) − P(A ∩ B)예요. A ∩ B = ∅인 두 사건을 서로 배반사건이라 하며 이때 P(A ∪ B) = P(A) + P(B)예요. A가 일어나지 않는 사건(여사건) Aᶜ의 확률은 P(Aᶜ) = 1 − P(A)예요.\n예: 1부터 20까지의 수 중 하나를 뽑을 때 2의 배수 또는 3의 배수일 확률은 (10 + 6 − 3)/20 = 13/20"),
        ce(.high, "확률", ["조건부확률", "conditional probability", "P(B|A)", "확률의 곱셈정리"], "사건 A가 일어났다는 조건에서 사건 B가 일어날 확률을 조건부확률 P(B|A)라 하고 P(B|A) = P(A ∩ B)/P(A) (P(A) > 0)이에요. 이로부터 확률의 곱셈정리 P(A ∩ B) = P(A)P(B|A)가 나와요.\n예: 주사위를 던져 짝수가 나왔을 때 그 눈이 4 이상일 확률은 P(A ∩ B)/P(A) = (2/6)/(3/6) = 2/3"),
        ce(.high, "확률", ["사건의 독립과 종속", "독립사건", "independent events"], "사건 A가 일어나는 것이 B가 일어날 확률에 영향을 주지 않을 때, 즉 P(B|A) = P(B)일 때 A와 B는 서로 독립이에요. A, B가 독립이면 P(A ∩ B) = P(A)P(B)이고, 독립이 아니면 종속이에요. 배반사건과 독립사건은 서로 다른 개념이에요.\n예: 동전과 주사위를 함께 던져 앞면과 6이 나올 확률은 1/2 × 1/6 = 1/12"),
        ce(.high, "확률", ["독립시행의 확률", "독립시행", "반복시행"], "같은 시행을 여러 번 반복할 때 각 시행의 결과가 서로 영향을 주지 않으면 독립시행이라고 해요. 한 번의 시행에서 A가 일어날 확률이 p일 때, n번의 독립시행에서 A가 정확히 r번 일어날 확률은 ₙCᵣpʳ(1 − p)ⁿ⁻ʳ이에요.\n예: 동전을 5번 던져 앞면이 정확히 3번 나올 확률은 ₅C₃(1/2)³(1/2)² = 10/32 = 5/16"),

        ce(.high, "통계", ["확률변수와 확률분포", "이산확률변수", "확률질량함수", "확률밀도함수"], "시행의 결과에 따라 값이 정해지는 변수를 확률변수라 하고, 그 값과 확률의 대응 관계를 확률분포라고 해요. 이산확률변수의 확률질량함수 P(X = xᵢ) = pᵢ는 0 ≤ pᵢ ≤ 1, Σpᵢ = 1을 만족해요. 연속확률변수는 확률밀도함수 그래프 아래 넓이로 확률을 나타내요.\n예: 동전 2개를 던질 때 앞면의 개수 X는 0, 1, 2이고 확률은 각각 1/4, 1/2, 1/4이에요."),
        ce(.high, "통계", ["이산확률변수의 기댓값과 분산", "평균 E(X)", "분산 V(X)", "표준편차 σ(X)"], "E(X) = Σxᵢpᵢ = m, V(X) = E((X − m)²) = E(X²) − {E(X)}², σ(X) = √V(X)예요. 상수 a, b에 대해 E(aX + b) = aE(X) + b, V(aX + b) = a²V(X)예요.\n예: 동전 2개를 던질 때 앞면의 개수 X에 대해 E(X) = 0 × 1/4 + 1 × 1/2 + 2 × 1/4 = 1, E(X²) = 1/2 + 1 = 3/2, V(X) = 3/2 − 1 = 1/2"),
        ce(.high, "통계", ["이항분포", "binomial distribution", "B(n, p)"], "한 번의 시행에서 사건 A가 일어날 확률이 p인 독립시행을 n번 반복할 때 A가 일어나는 횟수 X의 분포를 이항분포 B(n, p)라 하고 P(X = r) = ₙCᵣpʳqⁿ⁻ʳ (q = 1 − p)이에요. 평균은 E(X) = np, 분산은 V(X) = npq예요.\n예: 주사위를 180번 던질 때 1의 눈이 나오는 횟수 X는 B(180, 1/6)을 따르고 E(X) = 30, V(X) = 180 × 1/6 × 5/6 = 25, σ(X) = 5"),
        ce(.high, "통계", ["정규분포", "normal distribution", "N(m, σ²)"], "평균 m, 표준편차 σ인 정규분포 N(m, σ²)의 확률밀도함수 그래프는 직선 x = m에 대해 대칭인 종 모양이고, σ가 클수록 낮고 넓게 퍼져요. P(m − σ ≤ X ≤ m + σ) ≈ 0.6826, P(m − 2σ ≤ X ≤ m + 2σ) ≈ 0.9544, P(m − 3σ ≤ X ≤ m + 3σ) ≈ 0.9974예요.\n예: 점수가 N(70, 10²)을 따르면 50점 이상 90점 이하인 학생은 약 95.44%예요."),
        ce(.high, "통계", ["표준정규분포", "표준화", "Z = (X − m)/σ"], "평균 0, 분산 1인 정규분포 N(0, 1)을 표준정규분포라고 해요. X가 N(m, σ²)을 따르면 Z = (X − m)/σ는 N(0, 1)을 따르므로 표준정규분포표로 확률을 구해요. n이 충분히 크면 이항분포 B(n, p)는 정규분포 N(np, npq)에 가까워져요.\n예: X가 N(50, 4²)을 따를 때 P(X ≤ 58) = P(Z ≤ 2) = 0.5 + 0.4772 = 0.9772"),
        ce(.high, "통계", ["모집단과 표본", "표본평균의 분포", "표본평균"], "조사 대상 전체를 모집단, 그 일부를 표본이라 하고, 표본은 임의추출해야 해요. 모평균 m, 모표준편차 σ인 모집단에서 크기 n인 표본을 임의추출하면 표본평균 X̄에 대해 E(X̄) = m, V(X̄) = σ²/n이에요. 모집단이 정규분포이거나 n이 충분히 크면 X̄는 정규분포 N(m, σ²/n)을 따라요.\n예: m = 100, σ = 20, n = 16이면 E(X̄) = 100, σ(X̄) = 20/4 = 5"),
        ce(.high, "통계", ["모평균의 추정", "신뢰구간 추정", "통계적 추정"], "모표준편차가 σ인 정규모집단에서 크기 n인 표본의 평균이 x̄일 때, 모평균 m의 신뢰도 95% 신뢰구간은 x̄ − 1.96 × σ/√n ≤ m ≤ x̄ + 1.96 × σ/√n이고, 신뢰도 99%이면 1.96 대신 2.58을 써요. 표본의 크기가 클수록 신뢰구간이 짧아져요.\n예: σ = 10, n = 100, x̄ = 50이면 95% 신뢰구간은 48.04 ≤ m ≤ 51.96"),

        ce(.high, "이차곡선", ["포물선", "parabola", "초점과 준선"], "평면 위의 한 점 F(초점)와 이 점을 지나지 않는 한 직선(준선)에 이르는 거리가 같은 점들의 집합을 포물선이라고 해요. 초점이 (p, 0), 준선이 x = −p인 포물선의 방정식은 y² = 4px, 초점이 (0, p), 준선이 y = −p이면 x² = 4py예요.\n예: y² = 8x는 4p = 8에서 p = 2이므로 초점 (2, 0), 준선 x = −2"),
        ce(.high, "이차곡선", ["타원", "ellipse", "장축과 단축"], "평면 위의 두 정점 F, F′(초점)에서 거리의 합이 일정한 점들의 집합을 타원이라고 해요. 두 초점이 (c, 0), (−c, 0)이고 거리의 합이 2a이면 방정식은 x²/a² + y²/b² = 1 (a > b > 0, b² = a² − c²)이에요. 장축의 길이는 2a, 단축의 길이는 2b예요.\n예: x²/25 + y²/9 = 1은 c² = 25 − 9 = 16이므로 초점 (±4, 0), 장축 10, 단축 6"),
        ce(.high, "이차곡선", ["쌍곡선", "hyperbola", "점근선"], "평면 위의 두 정점 F, F′에서 거리의 차가 일정한 점들의 집합을 쌍곡선이라고 해요. 두 초점이 (±c, 0)이고 거리의 차가 2a이면 방정식은 x²/a² − y²/b² = 1 (c² = a² + b²)이고, 점근선은 y = ±(b/a)x, 주축의 길이는 2a예요.\n예: x²/9 − y²/16 = 1은 c² = 9 + 16 = 25이므로 초점 (±5, 0), 점근선 y = ±(4/3)x"),

        ce(.high, "벡터와 공간도형", ["벡터", "vector", "벡터의 크기"], "크기와 방향을 함께 가지는 양을 벡터라고 해요. 점 A에서 B로 향하는 벡터 AB의 크기는 선분 AB의 길이이고, 크기와 방향이 같으면 위치에 상관없이 같은 벡터예요. 성분으로 벡터 a = (a₁, a₂)이면 |a| = √(a₁² + a₂²)이에요.\n예: 벡터 (3, −4)의 크기는 √(9 + 16) = 5"),
        ce(.high, "벡터와 공간도형", ["벡터의 덧셈과 실수배", "벡터의 연산", "평행사변형법"], "두 벡터의 합은 한 벡터의 끝점에 다른 벡터의 시작점을 이어 그리거나(삼각형법) 평행사변형의 대각선으로 구해요. 성분으로는 (a₁, a₂) + (b₁, b₂) = (a₁ + b₁, a₂ + b₂), k(a₁, a₂) = (ka₁, ka₂)예요. 영벡터가 아닌 두 벡터 a, b가 평행하면 b = ka (k ≠ 0)예요.\n예: a = (1, 2), b = (3, −1)이면 2a − b = (2 − 3, 4 + 1) = (−1, 5)"),
        ce(.high, "벡터와 공간도형", ["벡터의 내적", "dot product", "inner product"], "두 벡터 a, b가 이루는 각이 θ일 때 내적은 a · b = |a||b|cos θ이고, 성분으로는 a₁b₁ + a₂b₂예요. 영벡터가 아닌 두 벡터가 수직이면 a · b = 0이에요. 두 벡터 사이의 각은 cos θ = (a · b)/(|a||b|)로 구해요.\n예: a = (1, 2), b = (4, −2)이면 a · b = 4 − 4 = 0이므로 두 벡터는 수직이에요."),
        ce(.high, "벡터와 공간도형", ["공간에서의 위치 관계", "꼬인 위치", "삼수선의 정리", "정사영"], "공간에서 두 직선은 한 점에서 만나거나, 평행하거나, 만나지도 평행하지도 않은 꼬인 위치에 있어요. 평면 α 밖의 점 P에서 α에 내린 수선의 발을 O, α 위의 직선 l에 내린 수선의 발을 H라 하면 OH ⊥ l이에요(삼수선의 정리). 넓이 S인 도형을 이루는 각이 θ인 평면에 정사영하면 넓이는 S cos θ예요.\n예: 정육면체에서 한 모서리와 꼬인 위치에 있는 모서리는 4개예요."),
        ce(.high, "벡터와 공간도형", ["공간좌표", "공간에서 두 점 사이의 거리", "구의 방정식"], "공간의 점은 세 좌표축으로 (x, y, z)처럼 나타내요. 두 점 A(x₁, y₁, z₁), B(x₂, y₂, z₂) 사이의 거리는 √((x₂ − x₁)² + (y₂ − y₁)² + (z₂ − z₁)²)이에요. 중심이 (a, b, c), 반지름이 r인 구의 방정식은 (x − a)² + (y − b)² + (z − c)² = r²이에요.\n예: A(1, 2, 3), B(3, 5, 9) 사이의 거리는 √(4 + 9 + 36) = 7"),

        // MARK: - 대학교

        ce(.university, "미적분학", ["엡실론-델타 논법", "극한의 엄밀한 정의", "epsilon-delta"], "lim(x→a) f(x) = L의 엄밀한 정의는 '임의의 ε > 0에 대해 어떤 δ > 0가 존재하여 0 < |x − a| < δ이면 |f(x) − L| < ε'이에요. 오차 ε를 아무리 작게 요구해도 x를 a에 충분히 가깝게(δ 이내로) 잡으면 그 요구를 만족시킬 수 있다는 뜻이에요.\n예: lim(x→2) (3x + 1) = 7은 |(3x + 1) − 7| = 3|x − 2|이므로 δ = ε/3로 잡으면 증명돼요."),
        ce(.university, "미적분학", ["평균값 정리", "mean value theorem", "롤의 정리 (Rolle's theorem)"], "f가 [a, b]에서 연속이고 (a, b)에서 미분가능하면 f′(c) = (f(b) − f(a))/(b − a)인 c ∈ (a, b)가 존재해요. 할선과 기울기가 같은 접선이 어딘가에 있다는 뜻이며, f(a) = f(b)인 경우가 롤의 정리예요. 도함수가 항상 0이면 상수함수라는 사실도 이 정리로 증명해요.\n예: f(x) = x²의 [1, 3]에서 (9 − 1)/2 = 4 = 2c이므로 c = 2"),
        ce(.university, "미적분학", ["로피탈의 정리", "L'Hôpital's rule"], "lim f(x)/g(x)가 0/0 또는 ∞/∞ 꼴이고 lim f′(x)/g′(x)가 존재하면 lim f(x)/g(x) = lim f′(x)/g′(x)예요(그 근방에서 g′(x) ≠ 0). 부정형이 아니면 쓸 수 없다는 점에 주의해요.\n예: lim(x→0) (1 − cos x)/x² = lim(x→0) sin x/(2x) = 1/2, lim(x→∞) x/eˣ = lim(x→∞) 1/eˣ = 0"),
        ce(.university, "미적분학", ["테일러 급수", "Taylor series", "매클로린 급수"], "무한 번 미분가능한 f를 a 근방에서 f(x) = Σ f⁽ⁿ⁾(a)(x − a)ⁿ/n! (n = 0, 1, 2, …)로 나타낸 것을 테일러 급수, a = 0인 경우를 매클로린 급수라고 해요. 유한 개 항까지 자른 테일러 다항식으로 함수를 근사하고, 오차는 나머지항으로 평가해요.\n예: eˣ = 1 + x + x²/2! + x³/3! + …, sin x = x − x³/3! + x⁵/5! − …이므로 sin 0.1 ≈ 0.1 − 0.001/6 ≈ 0.09983"),
        ce(.university, "미적분학", ["멱급수와 수렴반지름", "멱급수", "수렴반지름", "power series"], "Σ aₙ(x − c)ⁿ 꼴의 급수를 멱급수라고 해요. 멱급수에는 |x − c| < R에서 절대수렴하고 |x − c| > R에서 발산하는 수렴반지름 R이 있어요. 극한이 존재하면 R = lim |aₙ/aₙ₊₁|로 구할 수 있고, 경계 |x − c| = R에서는 따로 확인해야 해요.\n예: Σ xⁿ/n의 수렴반지름은 1이고, x = −1에서는 수렴, x = 1에서는 발산(조화급수)해요."),
        ce(.university, "미적분학", ["급수의 수렴판정법", "비교판정법", "비율판정법", "적분판정법"], "양항급수의 수렴은 비교판정법(알려진 급수와 크기 비교), 비율판정법(lim |aₙ₊₁/aₙ| < 1이면 수렴, > 1이면 발산), 적분판정법(Σf(n)과 ∫f(x)dx가 함께 수렴·발산) 등으로 판정해요. p급수 Σ 1/nᵖ는 p > 1일 때만 수렴해요.\n예: Σ 1/n²은 수렴하고 합은 π²/6, Σ n/2ⁿ은 비율이 (n + 1)/(2n) → 1/2 < 1이므로 수렴"),
        ce(.university, "미적분학", ["이상적분", "improper integral", "특이적분"], "적분 구간이 무한하거나 피적분함수가 구간 안에서 무한히 커지는 적분을 이상적분이라 하고, 극한으로 정의해요. 예를 들어 ∫₁^∞ f(x)dx = lim(t→∞) ∫₁ᵗ f(x)dx예요. ∫₁^∞ 1/xᵖ dx는 p > 1일 때만 수렴해요.\n예: ∫₁^∞ 1/x² dx = lim(t→∞) (1 − 1/t) = 1, ∫₀¹ 1/√x dx = lim(s→0+) (2 − 2√s) = 2"),

        ce(.university, "다변수 미적분학", ["편미분", "편도함수", "partial derivative"], "여러 변수 함수 f(x, y)에서 다른 변수를 상수로 보고 한 변수에 대해서만 미분한 것을 편미분이라 하고 ∂f/∂x, ∂f/∂y로 써요. 이계 편도함수가 연속이면 미분 순서를 바꿔도 같아요: ∂²f/∂x∂y = ∂²f/∂y∂x (클레로 정리).\n예: f(x, y) = x²y + 3y³이면 ∂f/∂x = 2xy, ∂f/∂y = x² + 9y², 혼합편도함수는 둘 다 2x"),
        ce(.university, "다변수 미적분학", ["그래디언트", "기울기 벡터", "gradient", "방향도함수"], "∇f = (∂f/∂x, ∂f/∂y, ∂f/∂z)를 f의 그래디언트라고 해요. 그래디언트는 f가 가장 빠르게 증가하는 방향을 가리키고, 그 크기가 최대 증가율이에요. 단위벡터 u 방향의 방향도함수는 ∇f · u이고, ∇f는 등위면(등고선)에 수직이에요.\n예: f(x, y) = x² + y²이면 ∇f(1, 2) = (2, 4), 방향 (3/5, 4/5)의 방향도함수는 6/5 + 16/5 = 22/5"),
        ce(.university, "다변수 미적분학", ["다변수 함수의 극값", "임계점", "안장점", "이계도함수 판정법"], "∇f = 0인 점을 임계점이라고 해요. 임계점에서 D = (∂²f/∂x²)(∂²f/∂y²) − (∂²f/∂x∂y)²를 계산해 D > 0이고 ∂²f/∂x² > 0이면 극소, D > 0이고 ∂²f/∂x² < 0이면 극대, D < 0이면 안장점이에요. D = 0이면 이 판정으로는 알 수 없어요.\n예: f = x² − y²은 원점에서 D = 2 × (−2) − 0 = −4 < 0이므로 안장점, f = x² + y²은 D = 4 > 0이므로 극소"),
        ce(.university, "다변수 미적분학", ["라그랑주 승수법", "Lagrange multiplier", "제약 조건 최적화"], "제약 조건 g(x, y) = c 아래에서 f(x, y)의 극값은 ∇f = λ∇g와 g = c를 동시에 만족하는 점에서 찾아요. 극값에서 f의 등고선과 제약 곡선이 서로 접하기 때문이에요. λ를 라그랑주 승수라고 해요.\n예: x + y = 10일 때 xy의 최댓값: ∇(xy) = (y, x) = λ(1, 1)에서 x = y = 5이므로 최댓값은 25"),
        ce(.university, "다변수 미적분학", ["중적분", "이중적분", "double integral", "푸비니 정리"], "영역 R 위에서 f(x, y)를 적분한 ∬R f dA는 곡면 z = f(x, y) 아래의 부피를 뜻해요. 푸비니 정리에 따라 연속함수의 이중적분은 한 변수씩 차례로 적분하는 반복적분으로 계산하고, 적분 순서를 바꿔도 같아요. 극좌표에서는 dA = r dr dθ예요.\n예: ∫₀¹∫₀² xy dx dy = ∫₀¹ 2y dy = 1, 단위원판의 넓이는 ∫(θ: 0 → 2π)∫(r: 0 → 1) r dr dθ = 2π × 1/2 = π"),
        ce(.university, "다변수 미적분학", ["선적분", "line integral", "보존장"], "곡선 C를 따라 벡터장 F를 적분한 ∫C F · dr = ∫ₐᵇ F(r(t)) · r′(t) dt는 힘 F가 한 일을 뜻해요. F = ∇f인 보존장이면 선적분은 경로와 무관하게 f(끝점) − f(시작점)이에요(선적분의 기본정리).\n예: F = (2x, 2y) = ∇(x² + y²)일 때 (0, 0)에서 (1, 2)까지의 선적분은 경로와 상관없이 5 − 0 = 5"),
        ce(.university, "다변수 미적분학", ["그린 정리", "Green's theorem", "스토크스 정리", "발산 정리"], "평면에서 반시계 방향의 단순 닫힌곡선 C로 둘러싸인 영역 D에 대해 ∮C (P dx + Q dy) = ∬D (∂Q/∂x − ∂P/∂y) dA예요. 선적분과 이중적분을 연결해 주며, 3차원으로 확장한 것이 스토크스 정리와 발산 정리예요.\n예: P = −y, Q = x이면 ∮C (−y dx + x dy) = ∬D 2 dA이므로 D의 넓이 = (1/2)∮C (x dy − y dx)"),

        ce(.university, "선형대수학", ["행렬의 곱셈", "행렬", "matrix multiplication"], "m×n 행렬 A와 n×p 행렬 B의 곱 AB는 m×p 행렬이고, (i, j) 성분은 A의 i행과 B의 j열의 성분끼리 곱해 더한 값이에요. 앞 행렬의 열 수와 뒤 행렬의 행 수가 같아야 곱할 수 있어요. 결합법칙과 분배법칙은 성립하지만 일반적으로 AB ≠ BA예요.\n예: [[1, 2], [3, 4]] × [[5], [6]] = [[1×5 + 2×6], [3×5 + 4×6]] = [[17], [39]]"),
        ce(.university, "선형대수학", ["역행렬", "inverse matrix", "가역행렬"], "정사각행렬 A에 대해 AB = BA = I(단위행렬)인 B를 A의 역행렬 A⁻¹이라고 해요. 역행렬이 존재할 필요충분조건은 det A ≠ 0이에요. A = [[a, b], [c, d]]의 역행렬은 (1/(ad − bc))[[d, −b], [−c, a]]이고, (AB)⁻¹ = B⁻¹A⁻¹예요.\n예: A = [[2, 1], [5, 3]]이면 ad − bc = 1이므로 A⁻¹ = [[3, −1], [−5, 2]]"),
        ce(.university, "선형대수학", ["행렬식", "determinant", "det"], "정사각행렬 A에 하나의 수 det A를 대응시킨 것을 행렬식이라고 해요. 2×2는 ad − bc이고, 3×3 이상은 여인수 전개로 계산해요. det(AB) = det A × det B, det(Aᵀ) = det A이며, |det A|는 A가 나타내는 변환이 넓이(부피)를 몇 배로 바꾸는지를 뜻해요.\n예: [[1, 2, 0], [0, 3, 1], [2, 0, 1]]의 행렬식은 1 × (3 − 0) − 2 × (0 − 2) + 0 = 7"),
        ce(.university, "선형대수학", ["가우스 소거법", "Gaussian elimination", "기본 행 연산", "행사다리꼴"], "연립일차방정식을 첨가행렬로 쓰고 기본 행 연산(두 행 교환, 한 행에 0이 아닌 수 곱하기, 한 행의 배수를 다른 행에 더하기)으로 행사다리꼴을 만들어 푸는 방법이에요. 해는 없거나, 하나뿐이거나, 무수히 많아요.\n예: x + y = 3, 2x − y = 0에서 둘째 행에서 첫째 행의 2배를 빼면 −3y = −6이므로 y = 2, x = 1"),
        ce(.university, "선형대수학", ["벡터공간", "vector space", "부분공간"], "벡터의 덧셈과 스칼라배가 정의되고 교환법칙, 결합법칙, 영벡터와 역원의 존재, 분배법칙 등 8가지 공리를 만족하는 집합을 벡터공간이라고 해요. 벡터공간의 부분집합이 영벡터를 포함하고 덧셈과 스칼라배에 닫혀 있으면 부분공간이에요.\n예: ℝ³에서 평면 x + y + z = 0은 부분공간이지만, x + y + z = 1은 영벡터를 포함하지 않아 부분공간이 아니에요."),
        ce(.university, "선형대수학", ["일차독립", "선형독립", "linear independence", "일차종속"], "벡터 v₁, …, vₖ에 대해 c₁v₁ + … + cₖvₖ = 0을 만족하는 계수가 c₁ = … = cₖ = 0뿐이면 일차독립, 그렇지 않으면 일차종속이에요. 일차종속이면 어떤 벡터가 나머지 벡터들의 일차결합으로 표현돼요.\n예: (1, 2), (2, 4)는 2(1, 2) − (2, 4) = 0이므로 일차종속, (1, 0), (1, 1)은 일차독립이에요."),
        ce(.university, "선형대수학", ["기저와 차원", "기저", "차원", "basis"], "벡터공간 V를 생성(span)하면서 일차독립인 벡터들의 집합을 V의 기저라고 해요. 기저의 원소 개수는 기저를 어떻게 잡아도 같고, 이를 V의 차원 dim V라고 해요. V의 모든 벡터는 기저의 일차결합으로 유일하게 나타낼 수 있어요.\n예: ℝ³의 표준기저는 {(1, 0, 0), (0, 1, 0), (0, 0, 1)}이고 dim ℝ³ = 3, 2×2 행렬 전체의 공간은 차원이 4예요."),
        ce(.university, "선형대수학", ["선형변환", "linear transformation", "일차변환", "차원 정리"], "벡터공간 사이의 함수 T가 T(u + v) = T(u) + T(v), T(cu) = cT(u)를 만족하면 선형변환이에요. 유한차원에서는 행렬 곱 T(x) = Ax로 나타낼 수 있고, A의 각 열은 표준기저 벡터의 상이에요. dim V = dim(핵) + dim(상)이에요(차원 정리).\n예: 평면에서 원점을 중심으로 θ만큼 회전하는 변환의 행렬은 [[cos θ, −sin θ], [sin θ, cos θ]]예요."),
        ce(.university, "선형대수학", ["고윳값과 고유벡터", "eigenvalue", "eigenvector", "특성방정식"], "정사각행렬 A에 대해 Av = λv (v ≠ 0)이면 λ를 고윳값, v를 고유벡터라고 해요. 고윳값은 특성방정식 det(A − λI) = 0의 근이고, 고유벡터는 A를 곱해도 방향이 바뀌지 않고 λ배만 되는 벡터예요. 고윳값의 합은 대각합(trace), 곱은 행렬식과 같아요.\n예: A = [[2, 1], [1, 2]]는 (2 − λ)² − 1 = 0에서 λ = 1, 3이고, λ = 3의 고유벡터는 (1, 1)"),
        ce(.university, "선형대수학", ["대각화", "diagonalization", "닮은 행렬"], "n×n 행렬 A가 일차독립인 고유벡터 n개를 가지면, 이 고유벡터를 열로 하는 행렬 P에 대해 P⁻¹AP = D(고윳값을 대각성분으로 하는 대각행렬)로 대각화할 수 있어요. 그러면 Aⁿ = PDⁿP⁻¹로 거듭제곱을 쉽게 구해요. 실대칭행렬은 항상 직교행렬로 대각화돼요.\n예: [[2, 1], [1, 2]]는 P = [[1, 1], [1, −1]]이면 P⁻¹AP = diag(3, 1)"),

        ce(.university, "미분방정식", ["미분방정식", "differential equation", "상미분방정식", "초기값 문제"], "미지의 함수와 그 도함수 사이의 관계식을 미분방정식이라고 해요. 한 변수 함수의 도함수만 포함하면 상미분방정식, 편도함수를 포함하면 편미분방정식이에요. 가장 높은 도함수의 차수를 계라 하고, 초기조건으로 일반해의 상수를 정해 특수해를 얻어요.\n예: y′ = 2x의 일반해는 y = x² + C이고, y(0) = 1이면 y = x² + 1"),
        ce(.university, "미분방정식", ["변수분리형 미분방정식", "separable equation", "변수분리법"], "dy/dx = g(x)h(y) 꼴은 dy/h(y) = g(x)dx처럼 변수를 양변으로 나눈 뒤 각각 적분해서 풀어요. 인구 증가, 방사성 붕괴, 냉각 법칙 등에 쓰여요.\n예: dy/dx = ky → dy/y = k dx → ln|y| = kx + C → y = Ae^(kx), y(0) = 100, k = 0.1이면 y = 100e^(0.1x)"),
        ce(.university, "미분방정식", ["1계 선형 미분방정식", "적분인자", "integrating factor"], "y′ + P(x)y = Q(x) 꼴은 적분인자 μ(x) = e^(∫P(x)dx)를 양변에 곱하면 좌변이 (μy)′가 되어 μy = ∫μQ dx + C로 풀 수 있어요.\n예: y′ + y = eˣ에서 μ = eˣ이므로 (eˣy)′ = e²ˣ, eˣy = e²ˣ/2 + C, y = eˣ/2 + Ce⁻ˣ"),
        ce(.university, "미분방정식", ["2계 상수계수 선형 미분방정식", "특성방정식 (미분방정식)", "제차 미분방정식", "미정계수법"], "ay″ + by′ + cy = 0은 y = e^(rx)를 대입한 특성방정식 ar² + br + c = 0의 근으로 풀어요. 서로 다른 실근 r₁, r₂이면 y = C₁e^(r₁x) + C₂e^(r₂x), 중근 r이면 y = (C₁ + C₂x)e^(rx), 허근 α ± βi이면 y = e^(αx)(C₁cos βx + C₂sin βx)예요.\n예: y″ − 3y′ + 2y = 0 → r² − 3r + 2 = 0 → r = 1, 2 → y = C₁eˣ + C₂e²ˣ"),

        ce(.university, "확률론", ["확률공간과 콜모고로프 공리", "확률의 공리", "확률공간"], "확률공간은 표본공간 Ω, 사건들의 모임 F, 확률측도 P로 이루어져요. 콜모고로프 공리는 ① 모든 사건 A에 대해 P(A) ≥ 0, ② P(Ω) = 1, ③ 서로 배반인 사건 A₁, A₂, …에 대해 P(∪Aᵢ) = ΣP(Aᵢ)예요. 확률의 모든 성질은 이 공리에서 유도돼요.\n예: 공리로부터 P(∅) = 0, P(Aᶜ) = 1 − P(A)를 증명할 수 있어요."),
        ce(.university, "확률론", ["확률변수", "random variable", "누적분포함수"], "확률변수는 표본공간의 각 결과에 실수를 대응시키는 함수예요. 누적분포함수 F(x) = P(X ≤ x)는 감소하지 않고 오른쪽 연속이며, x → −∞이면 0, x → ∞이면 1이에요. 이산형은 확률질량함수, 연속형은 확률밀도함수 f(x) = F′(x)로 분포를 나타내요.\n예: 지수분포 F(x) = 1 − e^(−λx) (x ≥ 0)의 밀도함수는 f(x) = λe^(−λx)"),
        ce(.university, "확률론", ["기댓값", "expectation", "기대값"], "확률변수 X의 기댓값은 이산형이면 E[X] = Σ x P(X = x), 연속형이면 E[X] = ∫ x f(x) dx예요. 기댓값은 선형성 E[aX + bY] = aE[X] + bE[Y]를 가지며, 이 성질은 X와 Y가 독립이 아니어도 성립해요.\n예: 공정한 주사위의 기댓값은 (1 + 2 + … + 6)/6 = 3.5, 주사위 두 개 눈의 합의 기댓값은 3.5 + 3.5 = 7"),
        ce(.university, "확률론", ["분산과 공분산", "variance", "covariance", "상관계수"], "분산 Var(X) = E[(X − μ)²] = E[X²] − (E[X])²은 퍼진 정도, 공분산 Cov(X, Y) = E[XY] − E[X]E[Y]는 함께 변하는 정도예요. 상관계수 ρ = Cov(X, Y)/(σ(X)σ(Y))는 −1 ≤ ρ ≤ 1이에요. Var(X + Y) = Var(X) + Var(Y) + 2Cov(X, Y)이고, 독립이면 공분산은 0이지만 역은 성립하지 않아요.\n예: 주사위 X는 E[X²] = 91/6이므로 Var(X) = 91/6 − 3.5² = 35/12"),
        ce(.university, "확률론", ["주요 확률분포", "포아송분포", "지수분포", "베르누이분포"], "베르누이분포(성공 확률 p, 평균 p), 이항분포 B(n, p)(평균 np, 분산 np(1 − p)), 포아송분포(P(X = k) = e^(−λ)λᵏ/k!, 평균과 분산 모두 λ), 지수분포(평균 1/λ), 정규분포 N(μ, σ²)가 자주 쓰여요. 포아송분포는 단위 시간에 드물게 일어나는 사건의 횟수를 나타내요.\n예: 한 시간에 평균 2통 오는 전화가 한 통도 안 올 확률은 e⁻² ≈ 0.135"),
        ce(.university, "확률론", ["큰수의 법칙", "대수의 법칙", "law of large numbers"], "평균이 μ이고 서로 독립이며 같은 분포를 따르는 확률변수들의 표본평균 X̄ₙ = (X₁ + … + Xₙ)/n은 n → ∞일 때 μ에 수렴해요. 그래서 시행을 많이 반복하면 상대도수가 실제 확률에 가까워져요.\n예: 동전을 10000번 던지면 앞면 비율의 표준편차는 √(0.25/10000) = 0.005라서 비율이 0.5에 매우 가까워요."),
        ce(.university, "확률론", ["중심극한정리", "central limit theorem", "CLT"], "평균 μ, 분산 σ²(유한)인 독립 동일분포 확률변수들의 표본평균 X̄는 원래 분포의 모양과 상관없이 n이 커지면 근사적으로 정규분포 N(μ, σ²/n)을 따라요. 즉 (X̄ − μ)/(σ/√n)은 표준정규분포에 가까워져요. 통계적 추정과 검정에서 정규분포를 쓸 수 있는 근거예요.\n예: 주사위(평균 3.5, 분산 35/12)를 100번 던진 눈의 평균은 근사적으로 N(3.5, 0.0292)를 따라요."),
        ce(.university, "확률론", ["베이즈 정리", "Bayes' theorem", "사후확률"], "P(A|B) = P(B|A)P(A)/P(B)이고, 분모는 전확률 공식 P(B) = Σ P(B|Aᵢ)P(Aᵢ)로 구해요. 새로운 정보 B를 관찰한 뒤 사전확률 P(A)를 사후확률 P(A|B)로 갱신하는 원리예요.\n예: 유병률 1%, 민감도 99%, 위양성률 5%인 검사에서 양성이면 실제 병이 있을 확률은 0.0099/(0.0099 + 0.0495) ≈ 0.167, 약 17%예요."),

        ce(.university, "통계학", ["신뢰구간", "confidence interval", "구간추정"], "모수가 포함될 것으로 기대되는 구간을 신뢰구간이라고 해요. 모표준편차를 알거나 표본이 크면 x̄ ± 1.96 × σ/√n이 95% 신뢰구간이고, 모표준편차를 모르고 표본이 작으면 t분포를 써요. 95%는 같은 방법을 반복할 때 약 95%의 구간이 참값을 포함한다는 뜻이에요.\n예: n = 400, x̄ = 52, s = 10이면 95% 신뢰구간은 52 ± 1.96 × 0.5 = [51.02, 52.98]"),
        ce(.university, "통계학", ["가설검정", "hypothesis testing", "귀무가설과 대립가설", "제1종 오류"], "귀무가설 H₀(차이나 효과가 없다)를 세우고, H₀가 참이라고 가정할 때 관측 결과가 얼마나 드문지로 기각 여부를 판단해요. 참인 H₀를 기각하는 제1종 오류의 확률이 유의수준 α, 거짓인 H₀를 기각하지 못하는 제2종 오류의 확률이 β이고, 1 − β를 검정력이라고 해요.\n예: 신약 검정에서 H₀: 효과 없음, H₁: 효과 있음, 유의수준 α = 0.05로 정해요."),
        ce(.university, "통계학", ["p-값", "p-value", "유의확률"], "p-값은 귀무가설이 참일 때 관측된 것만큼 또는 그보다 더 극단적인 결과가 나올 확률이에요. p-값이 유의수준 α보다 작으면 귀무가설을 기각해요. p-값은 귀무가설이 참일 확률이 아니며, 효과의 크기를 말해 주지도 않아요.\n예: 동전을 10번 던져 10번 모두 앞면이면 공정한 동전이라는 가정에서 단측 p-값은 (1/2)¹⁰ ≈ 0.001이므로 α = 0.05에서 기각해요."),
        ce(.university, "통계학", ["t-검정", "t분포", "t-test"], "모표준편차를 모르고 표본이 작을 때 t = (x̄ − μ₀)/(s/√n)이 자유도 n − 1인 t분포를 따른다는 성질로 평균을 검정해요. t분포는 정규분포보다 꼬리가 두껍고, 자유도가 커지면 표준정규분포에 가까워져요.\n예: n = 16, x̄ = 105, s = 8, μ₀ = 100이면 t = 5/2 = 2.5로, 자유도 15의 양측 5% 임계값 2.131보다 커서 귀무가설을 기각해요."),
        ce(.university, "통계학", ["회귀분석", "선형회귀", "최소제곱법", "regression"], "두 변수의 관계를 직선 ŷ = a + bx로 나타내는 방법이에요. 잔차 제곱합 Σ(yᵢ − ŷᵢ)²을 최소로 하는 최소제곱법으로 b = Σ(xᵢ − x̄)(yᵢ − ȳ)/Σ(xᵢ − x̄)², a = ȳ − bx̄를 구해요. 결정계수 R²은 y의 변동 중 모형이 설명하는 비율이에요.\n예: 자료 (1, 2), (2, 3), (3, 5)는 x̄ = 2, ȳ = 10/3, b = 3/2, a = 1/3이므로 ŷ = 1/3 + 1.5x"),

        ce(.university, "이산수학", ["명제논리", "propositional logic", "진리표", "드모르간 법칙"], "참·거짓을 판별할 수 있는 명제를 ¬(부정), ∧(그리고), ∨(또는), →(조건), ↔(쌍조건)으로 연결해 다뤄요. p → q는 p가 참이고 q가 거짓일 때만 거짓이며, 대우 ¬q → ¬p와 논리적으로 동치예요. 드모르간 법칙 ¬(p ∧ q) ≡ ¬p ∨ ¬q도 자주 써요.\n예: p → q ≡ ¬p ∨ q이고, 항상 참인 p ∨ ¬p를 항진명제라고 해요."),
        ce(.university, "이산수학", ["집합론 기초", "멱집합", "곱집합", "포함배제의 원리"], "집합 A의 모든 부분집합의 집합을 멱집합 P(A)라 하고, |A| = n이면 |P(A)| = 2ⁿ이에요. 곱집합 A × B = {(a, b) | a ∈ A, b ∈ B}의 원소 수는 |A| × |B|예요. 포함배제의 원리 |A ∪ B| = |A| + |B| − |A ∩ B|가 성립해요.\n예: A = {1, 2, 3}의 멱집합은 원소가 8개, A × {x, y}는 원소가 6개예요."),
        ce(.university, "이산수학", ["관계와 동치관계", "동치관계", "동치류", "equivalence relation"], "집합 A 위의 관계 R은 A × A의 부분집합이에요. 반사적(aRa), 대칭적(aRb이면 bRa), 추이적(aRb이고 bRc이면 aRc)인 관계를 동치관계라 하고, 동치관계는 집합을 서로 겹치지 않는 동치류로 분할해요. 반사적, 반대칭적, 추이적인 관계는 부분순서예요.\n예: 정수에서 'a − b가 3의 배수'는 동치관계이고, 동치류는 3으로 나눈 나머지가 0, 1, 2인 세 집합이에요."),
        ce(.university, "이산수학", ["단사, 전사, 전단사", "단사함수", "전사함수", "bijection"], "함수 f: A → B에서 f(a₁) = f(a₂)이면 a₁ = a₂일 때 단사(일대일), B의 모든 원소가 상이 될 때 전사, 둘 다 만족하면 전단사(일대일대응)라고 해요. 전단사 함수만 역함수를 가져요.\n예: f(x) = 2x는 정수 집합 ℤ에서 ℤ로의 함수로 보면 단사이지만 홀수가 상이 아니므로 전사가 아니고, 실수 ℝ에서 ℝ로의 함수로 보면 전단사예요."),
        ce(.university, "이산수학", ["그래프 이론", "graph theory", "꼭짓점과 변", "차수"], "그래프는 꼭짓점들과 이들을 잇는 변들로 이루어진 구조예요. 한 꼭짓점에 연결된 변의 수를 차수라 하고, 모든 차수의 합은 변의 수의 2배예요(악수 정리). 그래서 차수가 홀수인 꼭짓점은 항상 짝수 개예요. 사이클이 없는 연결그래프를 트리라 하며, 꼭짓점이 n개인 트리의 변은 n − 1개예요.\n예: 완전그래프 K₅의 변의 수는 5 × 4/2 = 10"),
        ce(.university, "이산수학", ["오일러 경로와 해밀턴 경로", "오일러 회로", "한붓그리기"], "모든 변을 정확히 한 번씩 지나는 경로를 오일러 경로라고 해요. 연결그래프에서 홀수 차수 꼭짓점이 0개이면 오일러 회로, 2개이면 오일러 경로가 존재해요(한붓그리기 조건). 모든 꼭짓점을 정확히 한 번씩 지나는 해밀턴 경로는 간단한 판정법이 알려져 있지 않아요.\n예: 쾨니히스베르크의 다리 문제는 홀수 차수 꼭짓점이 4개라 한붓그리기가 불가능해요."),
        ce(.university, "이산수학", ["비둘기집 원리", "pigeonhole principle"], "n + 1개 이상의 물건을 n개의 상자에 넣으면 적어도 한 상자에는 물건이 2개 이상 들어가요. 일반화하면 N개를 k개의 상자에 넣을 때 어떤 상자에는 ⌈N/k⌉개 이상 들어가요(⌈ ⌉는 올림).\n예: 367명이 모이면 생일이 같은 사람이 반드시 있고, 3가지 색 양말 중 4짝을 꺼내면 같은 색 한 켤레가 반드시 있어요."),
        ce(.university, "이산수학", ["합동식과 모듈러 연산", "modular arithmetic", "페르마의 소정리"], "a − b가 n의 배수이면 a ≡ b (mod n)이라 쓰고, 합동식은 덧셈·뺄셈·곱셈을 보존해요. 페르마의 소정리에 따르면 p가 소수이고 a가 p의 배수가 아니면 aᵖ⁻¹ ≡ 1 (mod p)이에요. RSA 같은 암호에 활용돼요.\n예: 2¹⁰ = 1024 = 11 × 93 + 1이므로 2¹⁰ ≡ 1 (mod 11), 따라서 2¹⁰⁰ = (2¹⁰)¹⁰ ≡ 1 (mod 11)"),

        ce(.university, "해석학", ["실수의 완비성", "상한 공리", "supremum"], "위로 유계이고 공집합이 아닌 실수의 부분집합은 반드시 최소 상계(상한, sup)를 가져요. 이 성질이 실수를 유리수와 구별하며, 단조수렴정리, 사잇값 정리 등 해석학의 많은 정리가 여기서 나와요.\n예: {x ∈ ℚ | x² < 2}는 실수에서 상한 √2를 갖지만, 유리수 안에서는 상한이 없어요."),
        ce(.university, "해석학", ["코시 수열", "Cauchy sequence"], "임의의 ε > 0에 대해 어떤 N이 있어 m, n > N이면 |aₘ − aₙ| < ε인 수열을 코시 수열이라고 해요. 항들끼리 점점 가까워지는 수열이며, 실수에서는 코시 수열인 것과 수렴하는 것이 같아요(완비성).\n예: 3, 3.1, 3.14, 3.141, …(π의 소수 전개)은 유리수로 된 코시 수열이지만 극한 π는 유리수가 아니에요."),
        ce(.university, "해석학", ["균등연속", "uniform continuity", "하이네-칸토어 정리"], "f가 집합 D에서 균등연속이라는 것은 임의의 ε > 0에 대해 점의 위치와 관계없는 하나의 δ > 0가 있어 |x − y| < δ이면 |f(x) − f(y)| < ε이라는 뜻이에요. 닫힌 유계구간에서 연속인 함수는 균등연속이에요(하이네-칸토어 정리).\n예: f(x) = x²은 [0, 1]에서 균등연속이지만 실수 전체에서는 아니고, 1/x는 (0, 1)에서 균등연속이 아니에요."),
        ce(.university, "해석학", ["볼차노-바이어슈트라스 정리", "Bolzano-Weierstrass theorem", "콤팩트 집합"], "실수에서 유계인 수열은 반드시 수렴하는 부분수열을 가져요. ℝⁿ에서 닫혀 있고 유계인 집합은 콤팩트하며(하이네-보렐 정리), 콤팩트 집합 위의 연속함수는 최댓값과 최솟값을 가져요(최대·최소 정리).\n예: (−1)ⁿ은 수렴하지 않지만 짝수 번째 항으로 이루어진 부분수열 1, 1, 1, …은 1에 수렴해요."),

        ce(.university, "추상대수학", ["군", "group", "아벨군"], "집합 G와 이항연산이 ① 결합법칙 ② 항등원의 존재 ③ 모든 원소의 역원 존재를 만족하면 군이라고 해요. 교환법칙까지 성립하면 아벨군(가환군)이에요.\n예: (ℤ, +)는 항등원이 0인 아벨군이고, 0이 아닌 실수의 곱셈도 군이에요. 하지만 정수의 곱셈은 2의 역원 1/2이 정수가 아니므로 군이 아니에요."),
